const number = 'number';
const keyword = 'keyword';
const identifier = 'identifier';
const operator = 'operator';
const string = 'string';
const equal = 'equal';
const ret = 'return';

class Token {
	constructor() {
		this._token = '';
	}

	set token(token) {
		this._token = token;
	}

	get token() {
		return this._token;
	}

	start(index, line, column) {
		this._start = { index, line, column };
	}

	end(index, line, column) {
		this._end = { index, line, column };
		if (this.type === identifier && isKeyword(this._token)) {
			this.type = keyword;
		}
	}

	get pos() {
		return "" + (this._start.line) + " col " + (this._start.column) + ""
	}

	isComplete() {
		return this._start && this._end;
	}

	isStarting() {
		return this._start && !this._end;
	}
}


class Tokenizer {
	constructor() {
		this._tokenList = [];
		this._index = 0;
	}

	parse(input) {
		this._index = 0;
		this._tokenList = [];
		this._line = 1;
		this._column = 1;

		this._token = new Token();

		while (this._index < input.length) {
			const char = input[this._index];

			if (char === '\n') {
				this._endIfStarting();
				this._line++;
				this._column = 1;
				this._index++;
				continue;
			}

			if (char === ' ' || char === '\t') {
				this._endIfStarting();
				this._nextCursor();
				continue;
			}

			if (isOperator(char)) {
				this._endIfStarting();
				this._singleCharToken(operator, char);
				continue;
			}

			if (isLetter(char)) {
				if (this._token.isStarting()) {
					this._token.token += char;
				} else {
					this._startToken(identifier, char);
				}
				this._nextCursor();
				continue;
			}

			if (isNumber(char)) {
				if (this._token.isStarting()) {
					this._token.token += char;
				} else {
					this._startToken(number, char);
				}
				this._nextCursor();
				continue;
			}


			if (char === '=') {
				this._endIfStarting();
				this._singleCharToken(equal, char);
				continue;
			}


			if (char === '(') {
				this._endIfStarting();
				this._singleCharToken('openParen', char);
				continue;
			}

			if (char === ')') {
				this._endIfStarting();
				this._singleCharToken('closeParen', char);
				continue;
			}

			if (char === '{') {
				this._endIfStarting();
				this._singleCharToken('openBrace', char);
				continue;
			}

			if (char === '}') {
				this._endIfStarting();
				this._singleCharToken('closeBrace', char);
				continue;
			}

			if (char === '[') {
				this._endIfStarting();
				this._singleCharToken('openSquareBracket', char);
				continue;
			}

			if (char === ']') {
				this._endIfStarting();
				this._singleCharToken('closeSquareBracket', char);
				continue;
			}

			if (char === ':') {
				this._endIfStarting();
				this._singleCharToken('colon', char);
				continue;
			}

			if (char === ';') {
				this._endIfStarting();
				this._singleCharToken('semicolon', char);
				continue;
			}

			if (char === ',') {
				this._endIfStarting();
				this._singleCharToken('comma', char);
				continue;
			}

			// TODO must change this if we want to use floating number
			if (char === '.') {
				this._endIfStarting();
				this._singleCharToken('dot', char);
				continue;
			}

			if (char === '"') {
				this._endIfStarting();
				this._startToken(string, char);

				this._nextCursor();
				let newChar = input[this._index];
				this._token.token += newChar;
				while(newChar !== '"' && this._index < input.length) {
					this._nextCursor();
					newChar = input[this._index];
					this._token.token += newChar;
				}
				this._nextCursor();
				this._endToken();
				continue;
			}


			throw new Error('Invalid character: ' + char + '('+ char.charCodeAt(0).toString(16) +') at ' + this._index + ' on line ' + this._line + ' column ' + this._column);
		}

		this._endIfStarting();

		return this._tokenList;
	}

	_endIfStarting() {
		if (this._token.isStarting()) {
			this._endToken();
		}
	}

	_startToken(type, firstChar) {
		this._token.type = type;
		this._token.start(this._index, this._line, this._column);
		this._token.token = firstChar;
	}

	_endToken() {
		this._token.end(this._index, this._line, this._column);
		this._tokenList.push(this._token);
		this._token = new Token();
	}

	_singleCharToken(type, char) {
		this._startToken(type, char);
		this._endToken();
		this._nextCursor();
	}

	_nextCursor() {
		this._index++;
		this._column++;
	}
}

/**
 * Below is the code generated Supported by standard GitHub tools
 */

/**
 * @param {string} input
 * @return {string}
 * @example
 * // returns 'hello'
 * unescapeString('"hello"');
 * @example
 * // returns 'hello'
 * unescapeString('"hello"');
 */

function isNumber(char) {
	return char >= '0' && char <= '9';
}

function isLetter(char) {
	return char >= 'a' && char <= 'z' || char >= 'A' && char <= 'Z';
}

function isOperator(char) {
	return char === '+' || char === '-' || char === '*' || char === '/';
}

function isKeyword(char) {
	return char === 'var' ||
		char === 'fn' ||
		char === 'if' ||
		char === 'else' ||
		char === 'while' ||
		char === 'for' ||
		char === 'return' ||
		char === 'break' ||
		char === 'continue' ||
		char === 'true' ||
		char === 'false' ||
		char === 'null';
}

function isString(char) {
	return char === '"';
}

function isSpace(char) {
	return char === ' ';
}

function isEnd(char) {
	return char === ';';
}

function isIdentifier(char) {
	return isLetter(char) || isNumber(char);
}

function isToken(char) {
	return isNumber(char) || isLetter(char) || isOperator(char) || isKeyword(char) || isString(char) || isSpace(char) || isEnd(char);
}

function isWhiteSpace(char) {
	return char === ' ' || char === '\n' || char === '\t';
}

function isQuote(char) {
	return char === '"';
}

function isEscape(char) {
	return char === '\\';
}

function isSlash(char) {
	return char === '/';
}

function isStar(char) {
	return char === '*';
}

function isLineTerminator(char) {
	return char === '\n';
}

module.exports = Tokenizer;

// Here, we will sync our database, create our application, and export this module so that we can use it in the bin directory, where we will be able to establish a server to listen and handle requests and responses;

// Require environmental variables if we are in development or testing;
if (process.env.NODE_ENV !== 'production') {
  require('./secrets');
}

// Module dependencies;
var express = require('express');
var path = require('path');
var cookieParser = require('cookie-parser');
var logger = require('morgan');
var helmet = require('helmet');
var compression = require('compression');

// Utilities;
var createLocalDatabase = require('./utilities/createLocalDatabase');
var seedDatabase = require('./utilities/seedDatabase');

// Our database instance;
var db = require('./database');

// Our apiRouter;
var apiRouter = require('./routes/index');

// A helper function to sync our database;
var syncDatabase = function () {
  if (process.env.NODE_ENV === 'production') {
    db.sync();
  }
  else {
    console.log('As a reminder, the forced synchronization option is on');
    db.sync({ force: true })
      .then(() => seedDatabase())
      .catch(err => {
        if (err.name === 'SequelizeConnectionError') {
          createLocalDatabase();
          seedDatabase();
        }
        else {
          console.log(err);
        }
      });
    }
};

// Instantiate our express application;
var app = express();

// A helper function to create our app with configurations and middleware;
var configureApp = function () {
  app.use(helmet());
  app.use(logger('dev'));
  app.use(express.json());
  app.use(express.urlencoded({ extended: false }));
  app.use(compression());
  app.use(cookieParser());

  // Mount our apiRouter;
  app.use('/api', apiRouter);

  // Error handling;
  app.use((req, res, next) => {
    if (path.extname(req.path).length) {
      var err = new Error('Not found');
      err.status = 404;
      next(err);
    }
    else {
      next();
    }
  });

  // More error handling;
  app.use((err, req, res, next) => {
    console.error(err);
    console.error(err.stack);
    res.status(err.status || 500).send(err.message || 'Internal server error.');
  });
};

// Main function declaration;
var bootApp = async function () {
  await syncDatabase();
  await configureApp();
};

// Main function invocation;
bootApp();

// Export our app, so that it can be imported in the www file;
module.exports = app;

// Forward Azure Monitor Logs to Syslog (via Event Hub)
// Developed as a sample for testing purpuses
// https://github.com/miguelangelopereira/azuremonitor2syslog
// miguelp@microsoft.com

module.exports = function (context, myEventHubMessage) {
    context.log("JavaScript eventhub trigger function called for message array " + (myEventHubMessage) + "");
    // initializing syslog
    try{
        var syslog = require("syslog-client");
    } catch (e) {
        throw e;
    }    


    // getting environment variables
    var SYSLOG_SERVER = GetEnvironmentVariable("SYSLOG_SERVER");
    var SYSLOG_PROTOCOL;
    if (GetEnvironmentVariable("SYSLOG_PROTOCOL")=="TCP") {
        SYSLOG_PROTOCOL = syslog.Transport.Tcp;
    } else {
        SYSLOG_PROTOCOL = syslog.Transport.Udp;
    }

    var SYSLOG_HOSTNAME;
    if (GetEnvironmentVariable("SYSLOG_HOSTNAME")==null) {
        SYSLOG_HOSTNAME = "azurefunction"
    } else {
        SYSLOG_HOSTNAME = GetEnvironmentVariable("SYSLOG_HOSTNAME");
    }

    var SYSLOG_PORT = GetEnvironmentVariable("SYSLOG_PORT");

    var SYSLOG_FACILITY;
    if (GetEnvironmentVariable("SYSLOG_FACILITY")==null) {
        SYSLOG_FACILITY = syslog.Facility.Local0;
    } else {
        SYSLOG_FACILITY = GetEnvironmentVariable("SYSLOG_FACILITY");
    }

    // options for syslog connection
    var options = {
        syslogHostname: SYSLOG_HOSTNAME,
        transport: SYSLOG_PROTOCOL,    
        port: SYSLOG_PORT,
        facility: SYSLOG_FACILITY
    };

    // log connection variables
    context.log('SYSLOG Server: ', SYSLOG_SERVER);
    context.log('SYSLOG Port: ', SYSLOG_PORT);
    context.log('SYSLOG Protocol: ', SYSLOG_PROTOCOL);
    context.log('SYSLOG Hostname: ', SYSLOG_HOSTNAME);
    context.log('SYSLOG Facility: ', SYSLOG_FACILITY);

    if ((SYSLOG_SERVER == null) || (SYSLOG_PORT == null) || (SYSLOG_PROTOCOL == null) || (SYSLOG_HOSTNAME == null)) {
        throw "Please setup environment variables. "
    }

    // log received message from event hub
    context.log("Event Hubs trigger function processed message:  " + (myEventHubMessage) + "");
    context.log('EnqueuedTimeUtc =', context.bindingData.enqueuedTimeUtc);
    context.log('SequenceNumber =', context.bindingData.sequenceNumber);
    context.log('Offset =', context.bindingData.offset);

    // create syslog client
    var client = syslog.createClient(SYSLOG_SERVER, options);

    // cycle through eventhub messages and send syslog
    myEventHubMessage.forEach(function (message, index) {
        if(typeof message === 'object'){

            var msg = JSON.parse(JSON.stringify(message));
            msg.records.forEach((m1, i) => {
                client.log(JSON.stringify(m1), options, function(error) {        
                    if (error) {
                        context.log("error sending message");
                        context.log(error);
                    } else {
                        context.log("sent message successfully");
                    }
                });
            });

        }
    });


      context.log("completed sending all messages");

    context.done();
};

