/**
 * creates a pair pair: (a,b) => pair
 */
function pair(a, b) {
  return { left: a, right: b };
}

/**
 * creates a stream from a string, string | Array<string> => stream
 */
function stream(stringOrArray) {
  // copy array or string to array
  var array = [...stringOrArray];
  return {
    head: function () { return array[0]; },
    tail: function () { return stream(array.slice(1)); },
    take: function (n) { return stream(array.slice(n)); },
    isEmpty: function () { return array.length === 0; },
    toString: function () { return array.map(s => (typeof s === "string" ? s : JSON.stringify(s))).join(""); },
    filter: function predicate { return stream(array.filter(predicate)); },
    log: function () {
      var s = stream(array);
      while (!s.isEmpty()) {
        console.log(s.head());
        s = s.tail();
      }
    }
  };
}

function eatNSymbol(n, symbolPredicate) {
  return function (stream) {
    if (n === 0) return stream;
    if (symbolPredicate(stream)) {
      return eatNSymbol(n - 1, symbolPredicate)(stream.tail());
    }
    throw new Error(
      "Caught error while eating " + (n) + " symbols"
    );
  };
}

function eatSpaces(tokenStream) {
  return eatSymbolsWhile(tokenStream, function s { return s.type === " "; });
}

function eatSpacesTabsAndNewLines(tokenStream) {
  return eatSymbolsWhile(tokenStream, function s { return s.type === " " || s.type === "\t" || s.type === "\n"; });
}

function eatSymbolsWhile(tokenStream, predicate) {
  var s = tokenStream;
  while (!tokenStream.isEmpty()) {
    if (!predicate(s.head())) break;
    s = s.tail();
  }
  return s;
}

/**
 *  Select one rule
 * @param  {...any} rules
 */
function or(...rules) {
  var accError = null;
  for (var i = 0; i < rules.length; i++) {
    try {
      return rules[i]();
    } catch (error) {
      accError = error;
    }
  }
  throw accError;
}

/**
 * Returns a value based on the predicate
 * @param {*} listOfPredicates
 * @param {*} defaultValue
 */
function returnOne(listOfPredicates, lazyDefaultValue = createDefaultEl) {
  return function input {
    for (var i = 0; i < listOfPredicates.length; i++) {
      if (listOfPredicates[i].predicate(input))
        return listOfPredicates[i].value(input);
    }
    return lazyDefaultValue(input);
  };
}

function evalScriptTag(scriptTag) {
  var globalEval = eval;
  var srcUrl = scriptTag?.attributes["src"]?.textContent;
  if (srcUrl) {
    return fetch(srcUrl)
      .then(function code { return code.text(); })
      .then(function code {
        globalEval(code);
      });
  } else {
    return new Promise(function (re) {
      globalEval(scriptTag.innerText);
      re(true);
    });
  }
}

