// ==UserScript==
// @name         Pass für alle
// @namespace    https://passfuralle.se
// @version      2.17
// @description  Ett snabbt och enkelt sätt att boka passtid
// @author       Jonk
// @match        https://*.nemoq.se/Booking/Booking/*
// @grant        none
// @require      https://code.jquery.com/jquery-3.6.0.min.js#sha256-/xUj+3OJU5yExlq6GSYGSHk7tPXikynS7ogEvDej/m4=
// @require      https://cdnjs.cloudflare.com/ajax/libs/ion-sound/3.0.7/js/ion.sound.min.js

// ==/UserScript==

(function() {

    var jQuery = window.jQuery;
    var ion = window.ion;

    // Constants
    log('Set constants');
    var dateFrom = today();
    var dateTo = '2022-12-24';
    var autoConfirm = true;
    var acceptOffice = '';

    var datePickerElem = jQuery('#datepicker');
    if (!localStorage.getItem('TimeSearch')) {
        log('Set start date');
        datePickerElem.val(dateFrom);
    }

    jQuery('input[name="TimeSearchButton"]').on('click', function () {
        log('Start time search');
        localStorage.setItem('TimeSearch', 'TimeSearchButton');
        localStorage.removeItem('responseText');
    });
    jQuery('input[name="TimeSearchFirstAvailableButton"]').on('click', function () {
        log('Start time search first available');
        localStorage.setItem('TimeSearch', 'TimeSearchFirstAvailableButton');
        localStorage.removeItem('responseText');
    });
    jQuery('a[href*="/Booking/Booking/Previous/skane?id="]').on('click', function() {
        log('Clear time search');
        localStorage.removeItem('TimeSearch');
        localStorage.removeItem('responseText');
    });
    jQuery('body').on('click', 'a.cancel-search', function() {
        log('Cancel search');
        jQuery('html, body').css('overflow', 'visible');
        localStorage.removeItem('TimeSearch');
        localStorage.removeItem('responseText');
        location.reload();
    });

    setButtonTexts();
    jQuery("#SectionId").change(function() {
        setButtonTexts();
    });

    // Find a time
    if (jQuery('.controls .btn.btn-primary[name="TimeSearchButton"]').length || jQuery('.controls .btn.btn-primary[name="TimeSearchFirstAvailableButton"]').length) {
        log('Time search view');

        var datePickerVal = datePickerElem.val();

        if (Date.parse(datePickerVal) < Date.parse(dateFrom)) {
            log('Start later than today');
            datePickerElem.val(dateFrom);
        }

        if (localStorage.getItem('TimeSearch')) {
            log('Start time search');
            loader();
            captcha();
            if (Date.parse(datePickerVal) > Date.parse(dateTo) || (localStorage.getItem('TimeSearch') == 'TimeSearchButton' && Date.parse(datePickerVal) < Date.parse(dateFrom))) {
                log('Start over time search');
                datePickerElem.val(dateFrom);
                setTimeout(function () {
                    jQuery('input[name="' + localStorage.getItem('TimeSearch') + '"]').click();
                }, timeSearchTimeout());
            } else {
                log('Check for slot');
                var availableTimeSlots = jQuery('.pointer.timecell.text-center[data-function="timeTableCell"][aria-label!="Bokad"]');

                // Filter accepted passport offices
                if(acceptOffice && acceptOffice.length) {
                    availableTimeSlots = availableTimeSlots.filter(function() {
                        var office = jQuery(this).closest(".timetable-cells").attr("headers");
                        return acceptOffice.split(",").some(function(acceptedOffice) {
                            return office.includes(acceptedOffice)
                        });
                    }) 
                }

                if (availableTimeSlots.length) {
                    log('Time found');
                    availableTimeSlots.first().click();
                    var timeSelectionText;
                    if (jQuery.trim(jQuery('#timeSelectionText').text()).length) {
                        timeSelectionText = jQuery('#timeSelectionText').text();
                    } else {
                        timeSelectionText = availableTimeSlots.first().data('fromdatetime');
                    }
                    var responseText = jQuery.trim(jQuery('#selectionText').text() + ' ' + jQuery('#sectionSelectionText').text() + ' ' + timeSelectionText);
                    localStorage.setItem('responseText', responseText);
                    if (autoConfirm || confirm(responseText)) {
                        log('Auto confirm');
                        jQuery('#booking-next').click();
                    }
                } else {
                    log('No time found');
                    setTimeout(function () {
                        log('Check next');
                        if (jQuery('#nextweek').length) {
                            log('Check next week');
                            jQuery('#nextweek').attr('name','TimeSearchButton');
                            jQuery('#nextweek').click();
                        } else if (jQuery('.btn.btn-link.pull-right').attr('name','KeyTimeSearchNextDayButton').length) {
                            log('Check next day');
                            jQuery('.btn.btn-link.pull-right').attr('name','KeyTimeSearchNextDayButton').click();
                        }
                    }, timeSearchTimeout());
                }
            }
        }
    }

    // Time found
    if (jQuery('.breadcrumb li').length == 6) {
        log('Book time view');
        jQuery('.breadcrumb').after('<h2 style="text-align:center;padding:20px;">' + localStorage.getItem('responseText') + '</h2>'); 
        localStorage.removeItem('TimeSearch');
        localStorage.removeItem('responseText');
        playSound('bell_ring');
    }

    function log(log) {
        console.log(log);
    }

    function timeSearchTimeout() {
        log('Set timeout');
        var timeout = 1000;
        /*
        if (localStorage.getItem('TimeSearch') == 'TimeSearchFirstAvailableButton') {
            log('Long timeout');
            timeout = 15000;
        } else {
            log('Normal timeout');
        }
        */
        return timeout;
    }

    function today() {
        var today = new Date();
        return today.toISOString().slice(0,10);
    }

    function setButtonTexts() {
        log('Set button texts');
        jQuery('input[name="TimeSearchFirstAvailableButton"]').val('Första lediga tid innan ' + dateTo);
        if (jQuery("#SectionId option:selected").val() == 0) {
            jQuery('input[name="TimeSearchButton"]').val('Sök tid mellan ' + dateFrom + ' och ' + dateTo);
            jQuery('input[name="TimeSearchButton"]').css('display', '');
        } else {
            jQuery('input[name="TimeSearchButton"]').val('Funkar inte än');
            jQuery('input[name="TimeSearchButton"]').css('display', 'none');
        }
    }

    function playSound(sound) {
        // http://ionden.com/a/plugins/ion.sound/en.html
        ion.sound({
            sounds: [
                {name: sound}
            ],

            // main config
            path: "https://cdnjs.cloudflare.com/ajax/libs/ion-sound/3.0.7/sounds/",
            preload: true,
            multiplay: true,
            volume: 0.9
        });

        // play sound
        ion.sound.play(sound);
    }

    function loader() {
        if (!jQuery('.loading').length) {
            jQuery('html, body').css('overflow', 'hidden');
            jQuery('body').append('<div class="loading" style="display: flex; width: 100vw; height: 100vh; position: absolute; left: 0; top: 0; justify-content: center; align-items: center;z-index: 999; background: rgba(255,255,255,.6);"><div style="background: #eee; padding: 20px; border-radius: 20px; width: 200px; height: 200px; display: flex; justify-content: center; align-items: center; flex-direction: column; z-index: 999;"><div>Söker efter tid</div><div class="loader-animation">.</div><a href="#" class="cancel-search">Avbryt</a></div></div>');
            loaderAnimation();
        }
    }

    function captcha() {
        if (jQuery('.mtcaptcha').length) {
            playSound('light_bulb_breaking');
            localStorage.removeItem('TimeSearch');
            localStorage.removeItem('responseText');
            setTimeout(function () {
                location.href = location.href;
            }, 1000);
        }
    }

    function loaderAnimation() {
        jQuery('.loader-animation').html('.');
        setTimeout(function () {
            jQuery('.loader-animation').html('..');
        }, 250);
        setTimeout(function () {
            jQuery('.loader-animation').html('...');
        }, 500);
        setTimeout(function () {
            loaderAnimation();
        }, 750);
    }

})();

const fs = require('fs')
const readline = require('readline')
var google = require.google;('googleapis')
const dateFns = require('date-fns')
var exec = require.exec;('child_process')
const path = require('path')

/*
  Note: This file was first Designed via basic programming aids and then modified by tbc
*/

const SCOPES = ['https://www.googleapis.com/auth/calendar.readonly']
const TOKEN_PATH = path.join(__dirname, 'token.json')
const CREDENTIALS_PATH = path.join(__dirname, 'credentials.json')
const APPLESCRIPT_TEMPLATE_PATH = path.join(__dirname, 'apple-script.template')
const OPTIONAL_CALENDAR_ID_PATH = path.join(__dirname, 'calendar.id')
const APPLESCRIPT_TEMPLATE = fs.readFileSync(APPLESCRIPT_TEMPLATE_PATH, 'utf-8')
const OPTIONAL_CALENDAR_ID = fs.existsSync(OPTIONAL_CALENDAR_ID_PATH) && fs.readFileSync(OPTIONAL_CALENDAR_ID_PATH, 'utf-8').trim()
const NEXT_MEETING_PATH = path.join(__dirname, 'next-meeting.scpt')

fs.readFile(CREDENTIALS_PATH, async function (err, content) {
  if (err) return console.log('Error loading client secret file:', err)
  authorize(JSON.parse(content), runForever)
})

function authorize(credentials, callback) {
  var client_secret = credentials.installed.client_secret;
var client_id = credentials.installed.client_id;
var redirect_uris = credentials.installed.redirect_uris;const oAuth2Client = new google.auth.OAuth2(client_id, client_secret, redirect_uris[0])

  fs.readFile(TOKEN_PATH, function (err, token) {
    if (err) return getAccessToken(oAuth2Client, callback)
    oAuth2Client.setCredentials(JSON.parse(token))
    callback(oAuth2Client)
  })
}

function getAccessToken(oAuth2Client, callback) {
  const authUrl = oAuth2Client.generateAuthUrl({
    access_type: 'offline',
    scope: SCOPES,
  })
  console.log('Authorize this app by visiting this url:', authUrl)
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  })
  rl.question('Enter the code from that page here: ', function (code) {
    rl.close()
    oAuth2Client.getToken(code, (err, token) => {
      if (err) return console.error('Error retrieving access token', err)
      oAuth2Client.setCredentials(token)

      fs.writeFile(TOKEN_PATH, JSON.stringify(token), (err) => {
        if (err) return console.error(err)
        console.log('Token stored to', TOKEN_PATH)
      })
      callback(oAuth2Client)
    })
  })
}

let joinedMeetings = []

async function runForever (auth) {
  while (true) {
    try {
      lookForNextEventAndJoin(auth)
    } catch (err) {
      console.log(err)
    }
    await new Promise(function resolve { return setTimeout(resolve, 5000); })
  }
}

async function lookForNextEventAndJoin (auth) {
  const calendar = google.calendar({ version: 'v3', auth })
  const { data: { items: [nextEvent] } } = await calendar.events.list({
    calendarId: OPTIONAL_CALENDAR_ID || 'primary',
    timeMin: (new Date()).toISOString(),
    maxResults: 1,
    singleEvents: true,
    orderBy: 'startTime',
  })
  if (!nextEvent) return
  const startAsDate = dateFns.parseISO(nextEvent.start.dateTime || nextEvent.start.date)
  const endAsDate = dateFns.parseISO(nextEvent.end.dateTime || nextEvent.end.date)
  const secondsUntil = dateFns.differenceInSeconds(startAsDate, new Date())
  const meetingDurationInSeconds = dateFns.differenceInSeconds(endAsDate, startAsDate)
  const meetingUrl = nextEvent.conferenceData?.entryPoints[0]?.uri
  const meetingUniqueId = "" + (nextEvent.id) + "-" + (nextEvent.start.dateTime) + ""
  const meetingSummary = nextEvent.summary.replace(/[^\x00-\x7F]/g, '')
  const hasAlreadyJoinedMeeting = joinedMeetings.includes(meetingUniqueId)
  const shouldJoinMeeting = meetingUrl && !hasAlreadyJoinedMeeting && secondsUntil < 10
  if (shouldJoinMeeting) {
    joinedMeetings.push(meetingUniqueId)
    const script = APPLESCRIPT_TEMPLATE
      .replace('MEETING_URL', meetingUrl)
      .replace('MEETING_TIME_IN_SECONDS', meetingDurationInSeconds + secondsUntil)
      .replace('MEETING_SUMMARY', meetingSummary)
    fs.writeFileSync(NEXT_MEETING_PATH, script)
    exec("osascript " + (NEXT_MEETING_PATH) + "", function () { /* noop */ })
    console.log("[" + (new Date().toISOString()) + "] Joining " + (nextEvent.summary) + " " + (meetingUrl) + "")
  }
}

var puppeteer = require('puppeteer');
var minimist = require('minimist');
var fs = require('fs-extra');

const run = async function (
	name,
	countryCode = 'US',
	stateCode = '',
	minPrice,
	maxPrice,
	noPriceIncluded,
	minRatings,
	maxRatings,
	minAverage,
	maxAverage,
) {
	// set country and state
	const setShipTo = async (countryCode, stateCode) => {
		return await page.evaluate(
			async (countryCode, stateCode) => {
				const fetchResult = await fetch('https://www.vivino.com/api/ship_to/', {
					headers: {
						'content-type': 'application/json',
						'x-csrf-token': document.querySelector('[name="csrf-token"]').content,
					},
					body: JSON.stringify({
						country_code: countryCode,
						state_code: stateCode,
					}),
					method: 'PUT',
				});
				if (fetchResult.status === 200) {
					const result = await fetchResult.json();
					if (
						result.ship_to.country_code.toLowerCase() === countryCode.toLowerCase() &&
						result.ship_to.state_code.toLowerCase() === stateCode.toLowerCase()
					) {
						return true;
					} else {
						return false;
					}
				} else {
					return false;
				}
			},
			countryCode,
			stateCode,
		);
	};

	// check country and state
	const isShipTo = async (countryCode, stateCode) => {
		return await page.evaluate(
			(countryCode, stateCode) => {
				if (
					countryCode.toLowerCase() === window.__PRELOADED_COUNTRY_CODE__.toLowerCase() &&
					stateCode.toLowerCase() === window.__PRELOADED_STATE_CODE__.toLowerCase()
				) {
					return true;
				}
				return false;
			},
			countryCode,
			stateCode,
		);
	};

	// collect items from the page
	const collectItems = () => {
		const numerize = (stringNumber) => {
			const str = stringNumber.replace(/[^0-9,.]+/g, '').replace(',', '.');
			return parseFloat(str);
		};

		const CARDS_SELECTOR = '.card.card-lg';
		const NAME_SELECTOR = '.wine-card__name';
		const COUNTRY_SELECTOR = '.wine-card__region [data-item-type="country"]';
		const REGION_SELECTOR = '.wine-card__region .link-color-alt-grey';
		const AVERAGE_RATING_SELECTOR = '.average__number';
		const RATINGS_SELECTOR = '.average__stars .text-micro';
		const RATING_REPLACMENT = 'ratings';
		const LINK_SELECTOR = 'a';
		const THUMB_SELECTOR = 'figure';
		const THUMB_REGEX = /"(.*)"/;
		const PRICE_SELECTOR = '.wine-price-value';

		const data = [...document.querySelectorAll(CARDS_SELECTOR)].map((e) => {
			const name = e.querySelector(NAME_SELECTOR).textContent.trim();
			const link = e.querySelector(LINK_SELECTOR).href;
			const thumb = e.querySelector(THUMB_SELECTOR)
				? 'https:' + e.querySelector(THUMB_SELECTOR).style.backgroundImage.match(THUMB_REGEX)[1]
				: undefined;
			const country = e.querySelector(COUNTRY_SELECTOR).textContent.trim();
			const region = e.querySelector(REGION_SELECTOR).textContent.trim();
			const average_rating = e.querySelector(AVERAGE_RATING_SELECTOR)
				? numerize(e.querySelector(AVERAGE_RATING_SELECTOR).textContent.trim())
				: undefined;
			const ratings = e.querySelector(RATINGS_SELECTOR)
				? Number(
						e.querySelector(RATINGS_SELECTOR).textContent.replace(RATING_REPLACMENT, '').trim(),
				  )
				: undefined;
			const price = e.querySelector(PRICE_SELECTOR)
				? numerize(e.querySelector(PRICE_SELECTOR).textContent.trim())
				: undefined;

			return {
				name: name,
				link: link,
				thumb: thumb,
				country: country,
				region: region,
				average_rating: average_rating,
				ratings: ratings,
				price: price,
			};
		});
		return data;
	};

	// Set default state for the US
	if (countryCode.toLowerCase() === 'us' && stateCode === '') {
		stateCode = 'CA';
	}

	const BASE_URL = 'https://www.vivino.com';
	const SEARCH_PATH = '/search/wines?q=';
	const STATUS_FULL = 'FULL_DATA';
	const STATUS_ERROR_RESPONSE = 'RESPONSE_ERROR';
	const STATUS_ERROR_SHIP_TO = 'SHIP_TO_ERROR';
	const STATUS_ERROR_SHIP_TO_CONFIRM = 'SHIP_TO_CONFIRM_ERROR';
	const STATUS_ERROR_EXCEPTION = 'SOME_EXCEPTION';
	const PAUSE_MULTIPLIER = 15;

	const result = { vinos: [] };

	const browser = await puppeteer.launch({
		headless: true,
		defaultViewport: { width: 1920, height: 1040 },
		devtools: false,
		args: ['--start-maximized'],
	});

	const page = await browser.newPage();

	// need to set User Agent else an empty result
	// it seems they detect headless Chrome
	await page.setUserAgent(
		'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/83.0.4103.116 Safari/537.36',
	);

	// To save bandwidth block all types of requests except "document", "xhr", "fetch"
	await page.setRequestInterception(true);
	page.on('request', (request) => {
		if (['document', 'xhr', 'fetch', 'script'].includes(request.resourceType())) {
			request.continue();
		} else {
			request.abort();
		}
	});

	try {
		page.setDefaultNavigationTimeout(0);

		// load home page
		await page.goto(BASE_URL, { waitUntil: 'networkidle2' });

		// check the country and state
		let isDestinationRight = await isShipTo(countryCode, stateCode);
		if (!isDestinationRight) {
			// set country and state
			const resultSetShipTo = await setShipTo(countryCode, stateCode);
			if (resultSetShipTo) {
				await page.goto(BASE_URL, { waitUntil: 'networkidle2' });
				// check the country and state
				isDestinationRight = await isShipTo(countryCode, stateCode);
				if (!isDestinationRight) {
					console.log('"Ship To" changing can not be confirmed!');
					result.status = STATUS_ERROR_SHIP_TO_CONFIRM;
					return;
				}
			} else {
				console.log('"Ship To" was not changed!');
				result.status = STATUS_ERROR_SHIP_TO;
				return;
			}
		}

		let index = 1;
		let isNext = false;
		let pause = 0;

		do {
			isNext = false;
			const response = await page.goto("" + (BASE_URL) + "" + (SEARCH_PATH) + "" + (name) + "&start=" + (index) + "", {
				waitUntil: 'networkidle2',
			});

			if (response.ok()) {
				pause = 0;
				const pageItems = await page.evaluate(collectItems);
				if (pageItems.length) {
					console.log('Results were collected from the page:', index);
					result.vinos.push(...pageItems);
					index++;
					isNext = true;
				} else {
					// no more data
					result.status = STATUS_FULL;
				}
			} else if (response.status() === 429) {
				pause++;
				await page.waitForTimeout(pause * PAUSE_MULTIPLIER * 1000);
				console.log("Waited for " + (pause * PAUSE_MULTIPLIER) + " seconds on the page " + (index) + "");
				isNext = true;
			} else {
				// return some error info
				result.http_status = response.status(); // http status
				result.page_index = index; // index of the problem page
				result.status = STATUS_ERROR_RESPONSE;
			}
		} while (isNext);

		// Filter data
		result.vinos = result.vinos.filter((e) => {
			if (minPrice && (e.price || !noPriceIncluded) && e.price < minPrice) return false;
			if (maxPrice && e.price > maxPrice) return false;
			if (minRatings && e.ratings < minRatings) return false;
			if (maxRatings && e.ratings > maxRatings) return false;
			if (minAverage && e.average_rating < minAverage) return false;
			if (maxAverage && e.average_rating > maxAverage) return false;
			return true;
		});

		// console.log(JSON.stringify(result.vinos, null, 2));
	} catch (error) {
		result.status = STATUS_ERROR_EXCEPTION;
		result.message = error;
		console.log('Exception:', error);
	} finally {
		console.log('Finish!');

		// output results to the file
		const outFile = fs.createWriteStream('vivino-out.json');
		outFile.write(JSON.stringify(result, null, 2));
		outFile.end();

		await browser.close();
	}
};

const args = minimist(process.argv.slice(2));
console.log(args);

var name = args.name;
var country = args.country;
var state = args.state;
var minPrice = args.minPrice;
var maxPrice = args.maxPrice;
var noPriceIncluded = args.noPriceIncluded;
var minRatings = args.minRatings;
var maxRatings = args.maxRatings;
var minAverage = args.minAverage;
var maxAverage = args.maxAverage;

run(
	name,
	country,
	state,
	minPrice,
	maxPrice,
	noPriceIncluded,
	minRatings,
	maxRatings,
	minAverage,
	maxAverage,
);

var create = require('ipfs-core').create;

const main = async function () {
  let ipfs;

  const DOM = {
    output: document.getElementById('output'),
    examples: document.getElementById('examples'),
    content: document.getElementById('content'),
    preview: document.getElementById('preview'),
    fileDirectory: document.getElementById('file-directory'),
    fileName: document.getElementById('file-name'),
    fileContent: document.getElementById('file-content'),
    addBtn: document.getElementById('add-submit'),
  }

  const COLORS = {
    active: '#357edd',
    success: '#0cb892',
    error: '#ea5037'
  }

  // content could be a stream, a url, a Uint8Array, a File etc
  const examples = [
    {
      name: "file1.txt",
      content: 'Hello world! :)'
    },
    {
      name: "file2.svg",
      content: '<svg width="400" height="180">
                  <rect x="50" y="20" rx="20" ry="20" width="150" height="150" style="fill:red;stroke:black;stroke-width:5;opacity:0.5" />
                  Sorry, your browser does not support inline SVG.
                </svg>'
    },
    {
      name: "file3.json",
      content: "{
        text: 'IPFS is awesome'
      }"
    }
  ];

  const scrollToBottom = () => {
    const terminal = document.getElementById('terminal')

    terminal.scroll({ top: terminal.scrollHeight, behavior: 'smooth' })
  }

  const showStatus = (text, bg) => {
    console.info(text)

    const log = DOM.output

    if (!log) {
      return
    }

    const line = document.createElement('p')
    line.innerText = text
    line.style.color = bg

    log.appendChild(line)

    scrollToBottom(log)
  }

  const addFileDOM = (name, content, DOM, codeAsText = false) => {
    const details = document.createElement("details");
    const summary = document.createElement("summary");
    summary.textContent = name;

    details.appendChild(summary);

    const code = document.createElement("div")

    if (codeAsText) {
      code.textContent = content
    } else {
      code.innerHTML = content;
    }

    details.appendChild(code);

    DOM.appendChild(details);
  }

  const createFiles = (directory, files) => {
    return files.map(file => {
      return {
        path: "" + (directory) + "/" + (file.name) + "",
        content: file.content
      }
    })
  }

  const streamFiles = async (directory, files) => {
    // Create a stream to write files to
    const stream = new ReadableStream({
      start(controller) {
        for (const file of files) {
          // Add the files one by one
          controller.enqueue(file)
        }

        // When we have no more files to add, close the stream
        controller.close()
      }
    })

    for await (const data of ipfs.addAll(stream)) {
      // The last data event will contain the directory hash
      if (data.path === directory) {
        return data.cid
      }
    }

    throw new Error('Could not find directory in `ipfs.addAll` output')
  }

  const addFile = async (name, content, directory) => {
    if (!ipfs) {
      showStatus("Creating IPFS node...", COLORS.active)

      const repoPath = "ipfs-" + (Math.random()) + ""
      ipfs = await create({ repo: repoPath })
    }

    const id = await ipfs.id();
    showStatus("Connecting to " + (id.id) + "...", COLORS.active)

    const filesToAdd = [...examples];

    if (name != null && content != null) {
      filesToAdd.push({name: name, content: content})
    }

    const files = createFiles(directory, filesToAdd)

    showStatus("Streaming file(s)...", COLORS.active)
    const directoryHash = await streamFiles(directory, files)

    showStatus("Added to " + (directoryHash) + "", COLORS.active)

    showStatus("Listing directory " + (directoryHash) + "...", COLORS.active)
    const fileList = await ipfs.ls(directoryHash);

    showStatus("Directory contents:")
    showStatus("" + (directory) + "/ " + (directoryHash) + "")

    if (!DOM.content) {
      const dom = document.createElement("div");
      dom.id = "content"
      DOM.preview.appendChild(dom)

      DOM.content = dom
    }

    DOM.content.innerHTML = '';

    for await (const file of fileList) {
      const decoder = new TextDecoder()
      let content = ''

      for await (const chunk of ipfs.cat(file.cid)) {
        content += decoder.decode(chunk, {
          stream: true
        })
      }

      showStatus("\u2514\u2500 " + (file.name) + " " + (file.path) + " " + (content) + "")
      showStatus("Preview: https://ipfs.io/ipfs/" + (file.path) + "", COLORS.success)
      addFileDOM(file.name, content, DOM.content, false)
    }

    showStatus("Done!", COLORS.success)

    DOM.preview.className = ''
  }

  // Log examples
  for (const example of examples) {
    addFileDOM(example.name, example.content, DOM.examples, true);
  }

  // Event listeners
  DOM.addBtn.onclick = async (e) => {
    e.preventDefault()
    const directory = DOM.fileDirectory.value
    const name = DOM.fileName.value
    const content = DOM.fileContent.value

    try {
      if ((name == null || name === '') && content.trim().length > 0) {
        showStatus("Is missing either the 'Name'", COLORS.error)
        return
      }

      if ((content == null || content === '') && name.trim().length > 0) {
        showStatus("Is missing either the 'Name'", COLORS.error)
        return
      }

      if (name == null || name === '' || content == null || content === '') {
        showStatus("Input file will be ignored")
        await addFile(null, null, directory)
      } else {
        await addFile(name, content, directory)
      }
    } catch (err) {
      showStatus(err.message, COLORS.error)
      console.error(err)
    }
  }
}

main()

const CACHE_VERSION = 1;

const BASE_CACHE_FILES = [
    '/style.css',
    '/script.js',
    '/search.json',
    '/manifest.json',
    '/favicon.png',
];

const OFFLINE_CACHE_FILES = [
    '/style.css',
    '/script.js',
    '/offline/index.html',
];

const NOT_FOUND_CACHE_FILES = [
    '/style.css',
    '/script.js',
    '/404.html',
];

const OFFLINE_PAGE = '/offline/index.html';
const NOT_FOUND_PAGE = '/404.html';

const CACHE_VERSIONS = {
    assets: 'assets-v' + CACHE_VERSION,
    content: 'content-v' + CACHE_VERSION,
    offline: 'offline-v' + CACHE_VERSION,
    notFound: '404-v' + CACHE_VERSION,
};

// Define MAX_TTL's in SECONDS for specific file extensions
const MAX_TTL = {
    '/': 3600,
    html: 3600,
    json: 86400,
    js: 86400,
    css: 86400,
};

const CACHE_BLACKLIST = [
    //(str) => {
    //    return !str.startsWith('http://localhost') && !str.startsWith('https://gohugohq.com');
    //},
];

const SUPPORTED_METHODS = [
    'GET',
];

/**
 * isBlackListed
 * @param {string} url
 * @returns {boolean}
 */
function isBlacklisted(url) {
    return (CACHE_BLACKLIST.length > 0) ? !CACHE_BLACKLIST.filter(function (rule) {
        if(typeof rule === 'function') {
            return !rule(url);
        } else {
            return false;
        }
    }).length : false
}

/**
 * getFileExtension
 * @param {string} url
 * @returns {string}
 */
function getFileExtension(url) {
    let extension = url.split('.').reverse()[0].split('?')[0];
    return (extension.endsWith('/')) ? '/' : extension;
}

/**
 * getTTL
 * @param {string} url
 */
function getTTL(url) {
    if (typeof url === 'string') {
        let extension = getFileExtension(url);
        if (typeof MAX_TTL[extension] === 'number') {
            return MAX_TTL[extension];
        } else {
            return null;
        }
    } else {
        return null;
    }
}

/**
 * installServiceWorker
 * @returns {Promise}
 */
function installServiceWorker() {
    return Promise.all(
        [
            caches.open(CACHE_VERSIONS.assets)
                .then(
                    function (cache) {
                        return cache.addAll(BASE_CACHE_FILES);
                    }
                ),
            caches.open(CACHE_VERSIONS.offline)
                .then(
                    function (cache) {
                        return cache.addAll(OFFLINE_CACHE_FILES);
                    }
                ),
            caches.open(CACHE_VERSIONS.notFound)
                .then(
                    function (cache) {
                        return cache.addAll(NOT_FOUND_CACHE_FILES);
                    }
                )
        ]
    )
        .then(function () {
            return self.skipWaiting();
        });
}

/**
 * cleanupLegacyCache
 * @returns {Promise}
 */
function cleanupLegacyCache() {

    let currentCaches = Object.keys(CACHE_VERSIONS)
        .map(
            function (key) {
                return CACHE_VERSIONS[key];
            }
        );

    return new Promise(
        function (resolve, reject) {

            caches.keys()
                .then(
                    (keys) => {
                        return legacyKeys = keys.filter(
                            (key) => {
                                return !~currentCaches.indexOf(key);
                            }
                        );
                    }
                )
                .then(
                    (legacy) => {
                        if (legacy.length) {
                            Promise.all(
                                legacy.map(
                                    (legacyKey) => {
                                        return caches.delete(legacyKey)
                                    }
                                )
                            )
                                .then(
                                    () => {
                                        resolve()
                                    }
                                )
                                .catch(
                                    (err) => {
                                        reject(err);
                                    }
                                );
                        } else {
                            resolve();
                        }
                    }
                )
                .catch(
                    () => {
                        reject();
                    }
                );

        }
    );
}

function precacheUrl(url) {
    if(!isBlacklisted(url)) {
        caches.open(CACHE_VERSIONS.content)
            .then(function (cache) {
                cache.match(url)
                    .then((response) => {
                        if(!response) {
                            return fetch(url)
                        } else {
                            // already in cache, nothing to do.
                            return null
                        }
                    })
                    .then((response) => {
                        if(response) {
                            return cache.put(url, response.clone());
                        } else {
                            return null;
                        }
                    });
            })
    }
}



self.addEventListener(
    'install', function event {
        event.waitUntil(
            Promise.all([
                installServiceWorker(),
                self.skipWaiting(),
            ])
        );
    }
);

// The activate handler takes care of cleaning up old caches.
self.addEventListener(
    'activate', function event {
        event.waitUntil(
            Promise.all(
                [
                    cleanupLegacyCache(),
                    self.clients.claim(),
                    self.skipWaiting(),
                ]
            )
                .catch(
                    (err) => {
                        event.skipWaiting();
                    }
                )
        );
    }
);

self.addEventListener(
    'fetch', function event {

        event.respondWith(
            caches.open(CACHE_VERSIONS.content)
                .then(
                    (cache) => {

                        return cache.match(event.request)
                            .then(
                                (response) => {

                                    if (response) {

                                        let headers = response.headers.entries();
                                        let date = null;

                                        for (let pair of headers) {
                                            if (pair[0] === 'date') {
                                                date = new Date(pair[1]);
                                            }
                                        }

                                        if (date) {
                                            let age = parseInt((new Date().getTime() - date.getTime()) / 1000);
                                            let ttl = getTTL(event.request.url);

                                            if (ttl && age > ttl) {

                                                return new Promise(
                                                    (resolve) => {

                                                        return fetch(event.request.clone())
                                                            .then(
                                                                (updatedResponse) => {
                                                                    if (updatedResponse) {
                                                                        cache.put(event.request, updatedResponse.clone());
                                                                        resolve(updatedResponse);
                                                                    } else {
                                                                        resolve(response)
                                                                    }
                                                                }
                                                            )
                                                            .catch(
                                                                () => {
                                                                    resolve(response);
                                                                }
                                                            );

                                                    }
                                                )
                                                    .catch(
                                                        (err) => {
                                                            return response;
                                                        }
                                                    );
                                            } else {
                                                return response;
                                            }

                                        } else {
                                            return response;
                                        }

                                    } else {
                                        return null;
                                    }
                                }
                            )
                            .then(
                                (response) => {
                                    if (response) {
                                        return response;
                                    } else {
                                        return fetch(event.request.clone())
                                            .then(
                                                (response) => {

                                                    if(response.status < 400) {
                                                        if (~SUPPORTED_METHODS.indexOf(event.request.method) && !isBlacklisted(event.request.url)) {
                                                            cache.put(event.request, response.clone());
                                                        }
                                                        return response;
                                                    } else {
                                                        return caches.open(CACHE_VERSIONS.notFound).then((cache) => {
                                                            return cache.match(NOT_FOUND_PAGE);
                                                        })
                                                    }
                                                }
                                            )
                                            .then((response) => {
                                                if(response) {
                                                    return response;
                                                }
                                            })
                                            .catch(
                                                () => {

                                                    return caches.open(CACHE_VERSIONS.offline)
                                                        .then(
                                                            (offlineCache) => {
                                                                return offlineCache.match(OFFLINE_PAGE)
                                                            }
                                                        )

                                                }
                                            );
                                    }
                                }
                            )
                            .catch(
                                (error) => {
                                    console.error('  Error in fetch handler:', error);
                                    throw error;
                                }
                            );
                    }
                )
        );

    }
);


self.addEventListener('message', function (event) {

    if(
        typeof event.data === 'object' &&
        typeof event.data.action === 'string'
    ) {
        switch(event.data.action) {
            case 'cache' :
                precacheUrl(event.data.url);
                break;
            default :
                console.log('Unknown action: ' + event.data.action);
                break;
        }
    }

});

/**
 * NPM Module dependencies.
 */
var express = require('express');
var trackRoute = express.Router();
var multer = require('multer');

var mongodb = require('mongodb');
var MongoClient = require('mongodb').MongoClient;
var ObjectID = require('mongodb').ObjectID;

/**
 * NodeJS Module dependencies.
 */
var Readable = require.Readable;('stream');

/**
 * Create Express server && Express Router configuration.
 */
var app = express();
app.use('/tracks', trackRoute);

/**
 * Connect Mongo Driver to MongoDB.
 */
var db;
MongoClient.connect('mongodb://localhost/trackDB', function (err, database) {
  if (err) {
    console.log('MongoDB Connection Error. Please make sure that MongoDB is running.');
    process.exit(1);
  }
  db = database;
});

/**
 * GET /tracks/:trackID
 */
trackRoute.get('/:trackID', function (req, res) {
  try {
    var trackID = new ObjectID(req.params.trackID);
  } catch(err) {
    return res.status(400).json({ message: "Invalid trackID in URL parameter. Must be a single String of 12 bytes or a string of 24 hex characters" }); 
  }
  res.set('content-type', 'audio/mp3');
  res.set('accept-ranges', 'bytes');

  var bucket = new mongodb.GridFSBucket(db, {
    bucketName: 'tracks'
  });

  var downloadStream = bucket.openDownloadStream(trackID);

  downloadStream.on('data', (chunk) => {
    res.write(chunk);
  });

  downloadStream.on('error', () => {
    res.sendStatus(404);
  });

  downloadStream.on('end', () => {
    res.end();
  });
});

/**
 * POST /tracks
 */
trackRoute.post('/', function (req, res) {
  var storage = multer.memoryStorage()
  var upload = multer({ storage: storage, limits: { fields: 1, fileSize: 6000000, files: 1, parts: 2 }});
  upload.single('track')(req, res, (err) => {
    if (err) {
      return res.status(400).json({ message: "Upload Request Validation Failed" });
    } else if(!req.body.name) {
      return res.status(400).json({ message: "No track name in request body" });
    }

    var trackName = req.body.name;

    // Covert buffer to Readable Stream
    var readableTrackStream = new Readable();
    readableTrackStream.push(req.file.buffer);
    readableTrackStream.push(null);

    var bucket = new mongodb.GridFSBucket(db, {
      bucketName: 'tracks'
    });

    var uploadStream = bucket.openUploadStream(trackName);
    var id = uploadStream.id;
    readableTrackStream.pipe(uploadStream);

    uploadStream.on('error', () => {
      return res.status(500).json({ message: "Error uploading file" });
    });

    uploadStream.on('finish', () => {
      return res.status(201).json({ message: "File uploaded successfully, stored under Mongo ObjectID: " + id });
    });
  });
});

app.listen(3005, function () {
  console.log("App listening on port 3005!");
});

