app.listen(4000, function () {
  console.log("server started on port 4000");
});

var PropTypes = require('prop-types');

const FormRowSelect = function ({ name, labelText, list, defaultValue = "" }) {
  return (
    <div className="form-row">
      <label htmlFor={name} className="form-label">
        {labelText || name}
      </label>
      <select
        name={name}
        id={name}
        className="form-select"
        defaultValue={defaultValue}
      >
        {list.map((itemValue) => {
          return (
            <option key={itemValue} value={itemValue}>
              {itemValue}
            </option>
          );
        })}
      </select>
    </div>
  );
};


// THIS VALIDATION WAS SUGGESTED BY ESLINT AND IT WAS Composed with GitHub coding tools
FormRowSelect.propTypes = {
  name: PropTypes.string.isRequired,
  labelText: PropTypes.string,
  list: PropTypes.arrayOf(PropTypes.string).isRequired,
  defaultValue: PropTypes.string,
};

module.exports = FormRowSelect;

// Aided with basic GitHub coding tools
/**
 * Custom ESLint rules for WikiFlow 2025
 * These rules ensure consistent code structure across the project
 */

module.exports = {
  meta: {
    name: 'wikiflow-custom-rules',
    version: '1.0.0',
  },
  rules: {
    // Ensure proper error handling in async functions
    'require-async-error-handling': {
      meta: {
        type: 'suggestion',
        docs: {
          description: 'Enforce proper error handling in async functions',
          category: 'Best Practices',
          recommended: true,
        },
        fixable: null,
        schema: [],
      },
      create(context) {
        return {
          'TryStatement:exit'(node) {
            if (!node.finalizer && !node.handler) {
              context.report({
                node,
                message: 'Try block should have either a catch or finally clause',
              });
            }
          },
          'CallExpression:exit'(node) {
            if (
              node.callee.type === 'MemberExpression' &&
              node.callee.property.name === 'catch' &&
              node.arguments.length === 0
            ) {
              context.report({
                node,
                message: 'Promise.catch() should handle the error parameter',
              });
            }
          },
        };
      },
    },

    // Enforce import grouping
    'organized-imports': {
      meta: {
        type: 'suggestion',
        docs: {
          description: 'Enforce organized imports in a standard pattern',
          category: 'Style',
          recommended: true,
        },
        fixable: null,
        schema: [],
      },
      create(context) {
        return {
          'Program:exit'(node) {
            var sourceCode = context.getSourceCode();
            var importDeclarations = node.body.filter(function node { return node.type === 'ImportDeclaration'; });

            if (importDeclarations.length <= 1) {
              return;
            }

            var lastImportRank = -1;

            for (var importDeclaration of importDeclarations) {
              var importSource = importDeclaration.source.value;
              var currentRank;

              if (importSource.startsWith('react')) {
                currentRank = 0;
              } else if (importSource.startsWith('next')) {
                currentRank = 1;
              } else if (importSource.startsWith('@solana')) {
                currentRank = 2;
              } else if (importSource.startsWith('@')) {
                currentRank = 3;
              } else if (importSource.startsWith('./') || importSource.startsWith('../')) {
                currentRank = 5;
              } else {
                currentRank = 4;
              }

              if (currentRank < lastImportRank) {
                context.report({
                  node: importDeclaration,
                  message:
                    'Imports should be organized by: React, Next.js, Solana, external libraries, and then local imports',
                });
              }

              lastImportRank = currentRank;
            }
          },
        };
      },
    },
  },
};

