/**
 * DIS functions for dealing with string.
 * If you're translator or sth, check DIS.lang as well
 * @namespace 
 */
DIS.string = (function(){
	var tags = [
		// color tags
		["<white>","\\c[0]"],
		["<yellow>","\\c[14]"],
		["<ltgreen>","\\c[1]"],
		["<green>","\\c[2]"],
		["<ltred>","\\c[5]"],
		["<red>","\\c[17]"],
		["<purple>","\\c[16]"],
		["<ltpurple>","\\c[7]"],
		["<ltblue>","\\c[10]"],
		["<blue>","\\c[11]"],
		["<glay>","\\c[4]"],

		// parameter tags
		["<HP>","\\c[12]HP\\c[0]"],
		["<AD>","\\c[17]AD\\c[0]"],
		["<AP>","\\c[16]AP\\c[0]"],
		["<AR>","\\c[4]AR\\c[0]"],
		["<MR>","\\c[16]MR\\c[0]"],
		["<HIT>","\\c[5]HIT\\c[0]"],
		["<EVA>","\\c[4]EVA\\c[0]"],
		["<WILL>","\\c[0]WILL\\c[0]"],
		["<MS>","\\c[10]MS\\c[0]"],
	];

	// return given char is CJK or not

	var isJapaneseChar = function(char) {
		var charCode = char.charCodeAt(0);
		return (
			(charCode >= 0x3000 && charCode <= 0x30ff) || // ひらがなとカタカナ Hiragana and Katakana
			(charCode >= 0x4e00 && charCode <= 0x9faf) || // CJK統合漢字 Kanji
			(charCode >= 0xff00 && charCode <= 0xffef)    // フルワイドのASCIIと半角・全角の形 other 2bytes char
		);
	};


	return {
		/**
		 * You can add DIS string tag by using this function.
		 * @param {[string,string]} mytag - [0] is tag, [1] is what will be replaced with the tag.
		 */
		addTag:function (mytag) {tags.push(mytag);},

		// return string
		getQstr: function(id) {
			var Adrt_Qstr_Head = 20000; // QuickString array starts from this number in DIS
			var string = gett(Adrt_Qstr_Head + id);
			return string;
		},

			// LEGACY map string
			getMapstr: function(id) { // ?
				var Adrt_mapstr_head = 40000
				var string = gett(Adrt_mapstr_head + id);
				return string;
			},

			/**
			 * replace tags in given string with actual RM color \c[n] format
			 * @param {string} given
			 * @return {string}
			 */
			replaceStringTags: function(given) {
				var rs = given;
				for (var tg of tags){
					rs = rs.replace(tg[0], tg[1]);
				};
				return rs; 
			},

			/**
			 * convert given js string into DIS basic format
			 * @param {string} given
			 * @return {string}
			 */
			convertString: function(given){

				var rs = given;



				var rsget = rs;
				if (rs.lastIndexOf('$mstr_') == 0){
					rs = rs.split("$mstr_")[1];
					rsget = RTS.mission.strings[rs];
				} else if (rs.lastIndexOf('$qstr_') == 0){
					rsget = rs.split("$qstr_")[1];
					// underconstruction
				};
				if (typeof rsget == "undefined") { errorlog('Map string "' + (rs) + '" is not registered.'); rs = "undefined";
				} else {
					rs = rsget;
				};

				deblog("" + (rs) + "")

				// replace color tags
				for (var tg of tags){
					rs = rs.replace(new RegExp(tg[0],"g"), tg[1]);
				}


				// let the in game string can reffer js variables
				// unco
				rs = rs.replace(/,/g, "$;");
				return rs // DIS format comma.

			},




			/**
			 * DIS.string.wrapText 
			 * returns LF inserted text .. needs to be improved for dealing with latin alphabet languages
			 * maybe add some new proc that attempts to go back to the last blank index I suppose? - TokyoHuskarl 
			 *
			 * @param {string} text
			 * @param {int} fontSize
			 * @param {int} maxWidth
			 * @returns {string} adjusted text
			 */
			wrapText: function(text, fontSize, maxWidth) {
				var englishCharWidth = fontSize * 0.5; // 英語文字の推定幅 supposed width of Latin Alphabet
				var japaneseCharWidth = fontSize * 0.9; // 日本語文字の推定幅 supposed width of 2bytes char
				var currentLine = '';
				var currentLineWidth = 0;
				var wrappedText = '';

				for (var char of text) {
					var charWidth = isJapaneseChar(char) ? japaneseCharWidth : englishCharWidth;

					if (char === '\n' || (currentLineWidth + charWidth) > maxWidth) {
						if (currentLine !== '') {
							wrappedText += currentLine + '\n';
							currentLine = '';
							currentLineWidth = 0;
						};
						if (char !== '\n') {
							currentLine += char;
							currentLineWidth += charWidth;
						};
					} else {
						currentLine += char;
						currentLineWidth += charWidth;
					};
				};

				if (currentLine.length > 0) {
					wrappedText += currentLine;
				};

				return wrappedText;
			},


			/**
			 * Convert given text into DIS UI format.
			 * DIS.string.convertString() is also called in this function
			 * UNDERCONSTRUCTION
			 * "{@AD}"
			 *
			 * @param {string} text
			 * @return {string} formatted text
			 */
			formatUIText: function(text){
				var res = this.convertString(text);
				res = res.replace(/\$,/g, ",");
				res = res.replace(/\^/g, "\n");
				return res;
			},
	};
})();




