		 * @return {bool} - continue evalQjs = true
		 */
		var evalQjs = function(st){
			if(st == "\\q"){
				dshmod = 0;
				dsLog("Quitting qjs mode...")
				return false;
			}
			try {
				eval(st);
				return true; 
			} catch(error){
				dsLog(error)
				return true;
			};
		};

		var dsLog = function(s){
			if(DEBUG == 0){console.log(s);};
			DIS.log.push(s);
		}

		var isArgHelpCalled = function () {return (args.length == 1) || args[1] == "--help"};

		var dshCmd = {

			echo(){

				/*
