	 * 
	 * @param {DATA_tech} tech - 
	 * @return {int} - should I convert this bool? idk
	 */
	ckTechFlag(tech){
		var techadd = tech.getFlagSlot();
		return this.playergamedata.techFlags[techadd[0]] & techadd[1];
	};

