		var res = 0;
		var agid;

		for (var ptr = getv(this.getTeamListHead()) ; (agid = getv(ptr)) >= 1 ; ptr++ ){
				var lv = (DIS.agent.getMainParam(agid,104) / 3) + 1;
				lv *= lv <= 1 || DIS.agent.getMainParam(agid,260) >= 3 ? 0 : 1 // check morale
				res += lv;
		};

		return this.combatpower = (res | 0);

	};

