// Bilinear picture size changing functions.
// NEED REORGANIZATION
// basically Drafted using standard development resources so you need to fix these anyway
// TODO: calc as float and round into int just before pushing into array.
function linearInterpolate(color1, color2, factor) {
	var a1 = (color1 >> 24) & 0xff;
	var r1 = (color1 >> 16) & 0xff;
	var g1 = (color1 >> 8) & 0xff;
	var b1 = color1 & 0xff;

	var a2 = (color2 >> 24) & 0xff;
	var r2 = (color2 >> 16) & 0xff;
	var g2 = (color2 >> 8) & 0xff;
	var b2 = color2 & 0xff;

	var r = Math.round(r1 + factor * (r2 - r1));
	var g = Math.round(g1 + factor * (g2 - g1));
	var b = Math.round(b1 + factor * (b2 - b1));
	var a = 0xff // Math.round(a1 + factor * (a2 - a1)); // With current 2003MP, you need not to consider about alpha channel

	return (a << 24) | (r << 16) | (g << 8) | b;
}

function getPixel(imageData, width, height, x, y) {
	if (x < 0 || x >= width || y < 0 || y >= height) {
		return 0; // If the pixel is out of picture, just return 0. 範囲外の場合は黒（または透明）を返す
	}
	return imageData[y * width + x];
}

function resizeImage(imageData, originalWidth, originalHeight,rate) {
	var newWidth = originalWidth * rate;
	var newHeight = originalHeight * rate;
	var resizedData = [];

	for (var y = 0; y < newHeight; y++) {
		for (var x = 0; x < newWidth; x++) {
			var srcX = (x / newWidth) * originalWidth;
			var srcY = (y / newHeight) * originalHeight;

			var x0 = Math.floor(srcX);
			var x1 = Math.min(Math.ceil(srcX), originalWidth - 1);
			var y0 = Math.floor(srcY);
			var y1 = Math.min(Math.ceil(srcY), originalHeight - 1);

			var factorX = srcX - x0;
			var factorY = srcY - y0;

			var p1 = getPixel(imageData, originalWidth, originalHeight, x0, y0);
			var p2 = getPixel(imageData, originalWidth, originalHeight, x1, y0);
			var p3 = getPixel(imageData, originalWidth, originalHeight, x0, y1);
			var p4 = getPixel(imageData, originalWidth, originalHeight, x1, y1);

			var p12 = linearInterpolate(p1, p2, factorX);
			var p34 = linearInterpolate(p3, p4, factorX);
			var pFinal = linearInterpolate(p12, p34, factorY);

			resizedData[y * newWidth + x] = pFinal;
		};
	};
	return resizedData;
};

/**
 * Class for rendering charts in Obsidian.
 * To be used with DataviewJS, Obsidian Charts and CustomJS plugins
 * @author Olivier C <olo06@hotmail.fr>
 */
 class DvCharts {

    /**
     * Render a chart on a daily basis with a custom attribute extracted from dailies pages
     * @param {object} args - object to pass containing properties used
     * @param {object} args.dv - dataview object to perform queries
     * @param {object} args.context - context to be set to **this**, used to render chart in place
     * @param {string} args.daysPath - path to Daily notes
     * @param {string} args.dayFormat - format of daily pages in Moment format
     * @param {string} args.attr - attribute to query and render the value
     * @param {string} args.label - label to display in chart for corresponding attr
     * @param {number} args.limit - numbers of last pages containing values to display
     */
    renderSingleAttrChart(args) {

        var dv = args.dv;
var context = args.context;
var daysPath = args.daysPath;
var dayFormat = args.dayFormat;
var attr = args.attr;
var label = args.label;
var limit = args.limit;

        var days = dv.pages(daysPath)
            .where(function p { return p[attr] && moment(p.file.name, dayFormat).isValid(); })
            .sort(function p { return p.file.name; })
            .filter(function (p, i, arr) { return i >= arr.length - limit; });

        var dates = [], attrData = [];
        days.forEach(function p {
            dates.push(p.file.name);
            attrData.push(p[attr]);
        });

        var chartData = {
            type: 'line',
            data: {
                labels: dates,
                datasets: [{
                    label,
                    data: attrData,
                    backgroundColor: 'rgba(85, 174, 229, 0.2)',
                    borderColor: 'rgba(85, 174, 229, 1)',
                    borderWidth: 1,
                    fill: true,
                    tension: 0.2
                }],
            }
        }

        window.renderChart(chartData, context.container);
    }

    /**
     * Render a chart on a weekly basis from the specified date
     * @param {object} args - object to pass containing properties used
     * @param {object} args.dv - dataview object to perform queries
     * @param {object} args.context - context to be set to **this**, used to render chart in place
     * @param {string} args.daysPath - path to Daily notes
     * @param {string} args.dayFormat - format of daily pages in Luxon format
     * @param {string} args.attributes - object with keys as attributes to query and values as metadatas
     * @param {object} args.template - default template for completing datasets metadatas
     * @param {string} args.type - set it to **'average'** to display average data in chart
     * @param {string} args.date - date in YYYY-MM-DD format from which weekly days will be retrieved
     */
    renderWeeklyChart(args) {

        var {
            dv,
            context,
            daysPath = '""',
            dayFormat = 'yyyy-MM-dd',
            template = {
                label: "Default",
                backgroundColor: 'rgba(255, 99, 132, 0.2)',
                borderColor: 'rgba(255, 99, 132, 1)',
                borderWidth: 1,
                fill: true,
                tension: 0.2
            },
            attributes,
            type,
            date
        } = args;

        var datasets = (function () {
            var startOfWeek = dv.date("sow");
            var getWeeklyDay = dayNum => dv.pages('"' + (daysPath) + '"').find(
                p => p.file.name == startOfWeek.plus({ days: dayNum }).toFormat(dayFormat));
            var weeklydays = Array.from({ length: 7 }, (c, i) => getWeeklyDay(i) || 0);
            var getData = (attr, props) => weeklydays.map(p =>
                (type == 'average') ? (p[attr] / props.average * 100) || 0 : p[attr]);
            var datasets = {};

            for (var [attr, props] of Object.entries(attributes)) {
                datasets[attr] = Object.assign({}, template, props, {data: getData(attr, props)});
            }

            return Object.values(datasets);
        })();

        var chartData = {
            type: 'line',
            data: {
                labels: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"],
                datasets,
            }
        }

        window.renderChart(chartData, context.container);
    }
}

// Require google from googleapis package.
var google = require.google;('googleapis')

// Require oAuth2 from our google instance.
var OAuth2 = google.auth.OAuth2;// Create a new instance of oAuth and set our Client ID & Client Secret.
var oAuth2Client = new OAuth2(
  'YOUR CLIENT ID GOES HERE',
  'YOUR CLIENT SECRET GOES HERE'
)

// Call the setCredentials method on our oAuth2Client instance and set our refresh token.
oAuth2Client.setCredentials({
  refresh_token: 'YOUR REFRESH TOKEN GOES HERE',
})

// Create a new calender instance.
var calendar = google.calendar({ version: 'v3', auth: oAuth2Client })

// Create a new event start date instance for temp uses in our calendar.
var eventStartTime = new Date()
eventStartTime.setDate(eventStartTime.getDay() + 2)

// Create a new event end date instance for temp uses in our calendar.
var eventEndTime = new Date()
eventEndTime.setDate(eventEndTime.getDay() + 4)
eventEndTime.setMinutes(eventEndTime.getMinutes() + 45)

// Create a dummy event for temp uses in our calendar
var event = {
  summary: "Meeting with David",
  location: "3595 California St, San Francisco, CA 94118",
  description: "Meet with David to talk about the new client project and how to integrate the calendar for booking.",
  colorId: 1,
  start: {
    dateTime: eventStartTime,
    timeZone: 'America/Denver',
  },
  end: {
    dateTime: eventEndTime,
    timeZone: 'America/Denver',
  },
}

// Check if we a busy and have an event on our calendar for the same time.
calendar.freebusy.query(
  {
    resource: {
      timeMin: eventStartTime,
      timeMax: eventEndTime,
      timeZone: 'America/Denver',
      items: [{ id: 'primary' }],
    },
  },
  function (err, res) {
    // Check for errors in our query and log them if they exist.
    if (err) return console.error('Free Busy Query Error: ', err)

    // Create an array of all events on our calendar during that time.
    var eventArr = res.data.calendars.primary.busy

    // Check if event array is empty which means we are not busy
    if (eventArr.length === 0)
      // If we are not busy create a new calendar event.
      return calendar.events.insert(
        { calendarId: 'primary', resource: event },
        err => {
          // Check for errors and log them if they exist.
          if (err) return console.error('Error Creating Calender Event:', err)
          // Else log that the event was created.
          return console.log('Calendar event successfully created.')
        }
      )

    // If event array is not empty log that we are busy.
    return console.log("Sorry I'm busy...")
  }
)

