		/**
		 * Change email
		 *
		 * check to see if users with same username exist
		 * if they do not exist then change email
		 */
		app.post('/changeEmail', sessionValidation, async function (req, res) {
			const filter = { username: req.session.username };
			const email = req.body.email;
			const usersCollection = db.collection('users');

			const schema = Joi.object(
				{
					email: Joi.string().email().max(40).required()
				}
			);

			var error = schema.validate.error;({ email });
			if (!(error)) {

				const existingUser = await usersCollection.findOne({ email: email });


				if (existingUser) {

					if (!(existingUser.username == req.session.username)) {
						res.render('changeEmail', { issue: false, issue2: true });
						return;
					}
				}

				const updateDoc = {
					$set: {
						email: email
					}
				};


				await usersCollection.updateOne(filter, updateDoc);
				req.session.email = email;
				const uploadSuccess = req.session.uploadSuccess;
				req.session.uploadSuccess = false; // Reset the flag immediately
