// auto Crafted with standard coding tools AI, make binary search tree in javascript
// URL : https://chat.openai.com/chat
class Node {
  constructor(value) {
    this.value = value;
    this.left = null;
    this.right = null;
  }
}

class BinarySearchTree {
  constructor() {
    this.root = null;
  }

  insert(value) {
    var newNode = new Node(value);
    if (this.root === null) {
      this.root = newNode;
      return this;
    }
    var current = this.root;
    while (true) {
      if (value === current.value) return undefined;
      if (value < current.value) {
        if (current.left === null) {
          current.left = newNode;
          return this;
        }
        current = current.left;
      } else {
        if (current.right === null) {
          current.right = newNode;
          return this;
        }
        current = current.right;
      }
    }
  }

  find(value) {
    if (this.root === null) return false;
    var current = this.root,
      found = false;
    while (current && !found) {
      if (value < current.value) {
        current = current.left;
      } else if (value > current.value) {
        current = current.right;
      } else {
        found = true;
      }
    }
    if (!found) return undefined;
    return current;
  }

  contains(value) {
    if (this.root === null) return false;
    var current = this.root,
      found = false;
    while (current && !found) {
      if (value < current.value) {
        current = current.left;
      } else if (value > current.value) {
        current = current.right;
      } else {
        return true;
      }
    }
    return false;
  }
}

var tree = new BinarySearchTree();
tree.insert(10);
tree.insert(5);
tree.insert(13);
tree.insert(11);
tree.insert(2);
tree.insert(16);
tree.insert(7);

console.log(tree.find(7));  // Node { value: 7, left: null, right: null }
console.log(tree.contains(15));  // false

var React = require('react');
require('./index.css');
var PropTypes = require('prop-types');

module.exports = class Wheel extends React.Component {;
  constructor(props) {
    super(props);
    this.state = {
      selectedItem: null,
      items: [],
      showModal: false,
    };
    this.selectItem = this.selectItem.bind(this);
    this.checkEmployeeId = this.checkEmployeeId.bind(this);
  }

  componentDidMount() {
    fetch("http://localhost:5001/projects")
      .then(function response { return response.json(); })
      .then(function data {
        this.setState({ items: data });
      })
      .catch(function error {
        console.error("Error fetching items:", error);
      });

    this.checkEmployeeId(this.props.employeeId); // Check employee ID on mount
  }

  checkEmployeeId(employeeId) {
    const approvedEmployeeIds = ["123", "456", "789"]; // Replace with actual approved employee IDs
    if (!approvedEmployeeIds.includes(employeeId)) {
      this.setState({ showModal: true });
    }
  }

  selectItem() {
    if (this.state.items.length === 0 || this.props.spinning === true) {
      console.log("Cant spin empty wheel");
      return;
    }
    if (this.state.selectedItem === null) {
      const selectedItem = Math.floor(Math.random() * this.state.items.length);
      this.props.onChange(selectedItem);
      if (this.props.onSelectItem) {
        this.props.onSelectItem(selectedItem);
      }
      this.setState({ selectedItem });
    } else {
      this.setState({ selectedItem: null });
      setTimeout(this.selectItem, 500);
    }
  }

  render() {
    var selectedItem = this.state.selectedItem;
var items = this.state.items;
var showModal = this.state.showModal;

    const wheelVars = {
      "--nb-item": items.length,
      "--selected-item": selectedItem,
    };
    const spinning = selectedItem !== null ? "spinning" : "";

    let spinDuration = localStorage.getItem("duration");

    let cssProperties = {};

    cssProperties["--spinning-duration"] = "" + (spinDuration) + "s";
    cssProperties["--wheel-color"] = "" + (this.props.wheelColor) + "";
    cssProperties["--neutral-color"] = "" + (this.props.fontColor) + "";

    if (cssProperties["--wheel-color"] === "null")
      cssProperties["--wheel-color"] = "#d38c12";

    if (cssProperties["--neutral-color"] === "null")
      cssProperties["--neutral-color"] = "#FFFFFF";

    return (
      <div style={cssProperties}>
        {showModal && (
          <div className="modal">
            <p>Employee is not entitled</p>
          </div>
        )}
        <div className="wheel-container" style={{ opacity: showModal ? 0.7 : 1 }}>
          <div
            lg={true}
            className={"wheel " + (spinning) + ""}
            style={wheelVars}
            onClick={this.selectItem}
          >
            {items.map(function (item, index) { return (
              <div
                className="wheel-item"
                key={index}
                style={{ "--item-nb": index }}
              >
                {index % 4 === 0 && 'Spin the wheel'}
              </div>
            ); })}
          </div>
        </div>
      </div>
    );
  }
}

// Define prop types
Wheel.propTypes = { 
  onChange: PropTypes.func.isRequired,
  onSelectItem: PropTypes.func,
  spinning: PropTypes.bool,
  wheelColor: PropTypes.string,
  fontColor: PropTypes.string,
  employeeId: PropTypes.string.isRequired, // Add employeeId prop type
};

// Define default prop values
Wheel.defaultProps = {
  onChange: function () {},
  spinning: false,
  wheelColor: "#d38c12",
  fontColor: "#FFFFFF",
};

