var stringify = require('query-string').stringify;
import {
    fetchUtils,
    GET_LIST,
    GET_ONE,
    CREATE,
    UPDATE,
    UPDATE_MANY,
    DELETE,
    DELETE_MANY,
    GET_MANY,
    GET_MANY_REFERENCE,
} from 'react-admin';


/**
 * Maps react-admin queries to the default format of Django REST Framework
 */
const drfProvider = function (apiUrl, httpClient=fetchUtils.fetchJson) {

    /**
     * @param {String} type React-admin request type, e.g. 'GET_LIST'
     * @param {String} resource Name of the resource to fetch, e.g. 'posts'
     * @param {Object} params Request parameters. Depends on the request type
     * @returns {Object} { url, options } The HTTP request parameters
     */
    const convertDataRequestToHttp = (type, resource, params) => {
        let url = "";
        let options = {};

        switch(type){
            case CREATE:
                url = "" + (apiUrl) + "/" + (resource) + "/";
                options.method = 'POST';
                options.body = JSON.stringify(params.data);
                break;
            case GET_ONE:
                url = "" + (apiUrl) + "/" + (resource) + "/" + (params.id) + "/";
                break;
            case GET_LIST: {
                var page = params.pagination.page;
var perPage = params.pagination.perPage;
                var field = params.sort.field;
var order = params.sort.order;
                var filter = params.filter;
                const query = {
                    page,
                    page_size: perPage,
                    ordering: "" + (order === 'ASC' ? '' : '-') + "" + (field) + "",
                    ...filter
                };
                url = "" + (apiUrl) + "/" + (resource) + "/?" + (JSON.stringify(query)) + "";
                break;
            }
            case GET_MANY_REFERENCE: {
                var page = params.pagination.page;
var perPage = params.pagination.perPage;
                var field = params.sort.field;
var order = params.sort.order;
                var filter = params.filter;
var target = params.target;
var id = params.id;
                const query = {
                    page,
                    page_size: perPage,
                    ordering: "" + (order === 'ASC' ? '' : '-') + "" + (field) + "",
                    ...filter,
                    [target]: id
                };
                url = "" + (apiUrl) + "/" + (resource) + "/?" + (JSON.stringify(query)) + "";
                break;
            }
            case UPDATE:
                url = "" + (apiUrl) + "/" + (resource) + "/" + (params.id) + "/";
                options.method = 'PUT';
                options.body = JSON.stringify(params.data);
                break;
            case DELETE:
                url = "" + (apiUrl) + "/" + (resource) + "/" + (params.id) + "/";
                options.method = 'DELETE';
                break;
            default:
                throw new Error("Unsupported Data Provider request type " + (type) + "");
        }

        return { url, options };
    }

    /**
     * @param {Object} response HTTP response from fetch()
     * @param {String} type React-admin request type, e.g. 'GET_LIST'
     * @param {String} resource Name of the resource to fetch, e.g. 'posts'
     * @param {Object} params Request parameters. Depends on the request type
     * @returns {Object} Data response
     */
    const convertHttpResponse = (response, type, resource, params) => {
        var headers = response.headers;
var json = response.json;

        switch (type) {
            case GET_LIST:
            case GET_MANY_REFERENCE:
                if ('count' in json){
                    return { data: json.results, total: json.count }
                } else if (headers.has('content-range')) {
                    return {
                        data: json,
                        total: parseInt(
                            headers
                            .get('content-range')
                            .split('/')
                            .pop(),
                            10
                        ),
                    };
                } else if ('detail' in json && json.detail === 'Invalid page.') {
                    return { data: [], total: 0 }
                } else {
                    throw new Error(
                        'The total number of results is unknown. The DRF data provider ' +
                        'expects responses for lists of resources to contain this ' +
                        'information to build the pagination. If you\'re not using the ' +
                        'default PageNumberPagination class, please include this ' +
                        'information using the Content-Range header OR a "count" key ' +
                        'inside the response.'
                    );
                }
            case CREATE:
                return { data: { ...params.data, id: json.id } };
            case DELETE:
                return { data: params.previousData };
            default:
                return { data: json };
        }
    }

    /**
     * @param {String} type React-admin request type, e.g. 'GET_LIST'
     * @param {string} resource Name of the resource to fetch, e.g. 'posts'
     * @param {Object} params Request parameters. Depends on the request type
     * @returns {Promise} the Promise for a data response
     */
    return (type, resource, params) => {
        /**
         * Split GET_MANY, UPDATE_MANY and DELETE_MANY requests into multiple promises,
         * since they're not supported by default.
         */
        switch (type) {
            case GET_MANY:
                return Promise.all(
                    params.ids.map(id =>
                        httpClient("" + (apiUrl) + "/" + (resource) + "/" + (id) + "/", {
                            method: 'GET'
                        })
                    )
                ).then(responses => ({
                    data: responses.map(response => response.json),
                }));
            case UPDATE_MANY:
                return Promise.all(
                    params.ids.map(id =>
                        httpClient("" + (apiUrl) + "/" + (resource) + "/" + (id) + "/", {
                            method: 'PUT',
                            body: JSON.stringify(params.data),
                        })
                    )
                ).then(responses => ({
                    data: responses.map(response => response.json),
                }));
            case DELETE_MANY:
                return Promise.all(
                    params.ids.map(id =>
                        httpClient("" + (apiUrl) + "/" + (resource) + "/" + (id) + "/", {
                            method: 'DELETE',
                        })
                    )
                ).then(responses => ({
                    data: responses.map(response => response.json),
                }));
            default:
                break;
        }

        var url = convertDataRequestToHttp.url;
var options = convertDataRequestToHttp.options;(type, resource, params);
        return httpClient(url, options)
            .then(response => convertHttpResponse(response, type, resource, params));
    }
}

module.exports = drfProvider;

const jwt = require('jsonwebtoken');
const fs = require('fs');

// Aided with basic GitHub coding tools - OWASP compliant Auth Middleware

class AuthMiddleware {
    constructor() {
        this.JWT_SECRET = process.env.JWT_SECRET || 'ca37cc84426514b08923818813192c3cb84a8a16';
        this.failedAttempts = new Map(); // Email -> { count, lastAttempt, lockoutUntil }
        this.MAX_FAILED_ATTEMPTS = 5;
        this.LOCKOUT_BASE_TIME = 60 * 1000; // 1 minut
        this.LOCKOUT_MAX_TIME = 24 * 60 * 60 * 1000; // 24 ore
    }

    /**
     * Verifică dacă user este admin și poate accesa CPanel
     * @param {Object} req - Express request object
     * @param {Object} res - Express response object  
     * @param {Function} next - Express next function
     */
    static requireAdmin(req, res, next) {
        try {
            const authHeader = req.headers.authorization;

            if (!authHeader || !authHeader.startsWith('Bearer ')) {
                SecurityLogger.logRoleAccess(null, 'unknown', req.path, false, req.ip);
                return res.status(401).json({
                    error: 'Token de autentificare lipsa. Acces interzis.'
                });
            }

            const token = authHeader.split(' ')[1];

            if (!token) {
                return res.status(401).json({
                    error: 'Format token invalid.'
                });
            }

            const decoded = jwt.verify(token, process.env.JWT_SECRET || 'ca37cc84426514b08923818813192c3cb84a8a16');

            // Verifică rolul admin
            if (decoded.role !== 'admin') {
                SecurityLogger.logRoleAccess(decoded.userId, decoded.role, req.path, false, req.ip);
                return res.status(403).json({
                    error: 'Acces interzis. Doar administratorii pot accesa CPanel-ul.',
                    redirectTo: decoded.role === 'client' ? '/client/schedule-menu' : '/login'
                });
            }

            // Log successful admin access
            SecurityLogger.logRoleAccess(decoded.userId, 'admin', req.path, true, req.ip);

            req.user = decoded;
            req.adminAccess = true;
            next();

        } catch (error) {
            SecurityLogger.logSuspiciousActivity(null, 'INVALID_ADMIN_TOKEN', {
                path: req.path,
                ip: req.ip,
                error: error.message
            });

            return res.status(401).json({
                error: 'Token invalid sau expirat.'
            });
        }
    }

    /**
     * Verifică dacă user este client și poate accesa meniul de programări
     * @param {Object} req - Express request object
     * @param {Object} res - Express response object
     * @param {Function} next - Express next function
     */
    static requireClient(req, res, next) {
        try {
            const authHeader = req.headers.authorization;

            if (!authHeader || !authHeader.startsWith('Bearer ')) {
                return res.status(401).json({
                    error: 'Token de autentificare lipsa. Te rugăm să te loghezi.'
                });
            }

            const token = authHeader.split(' ')[1];
            const decoded = jwt.verify(token, process.env.JWT_SECRET || 'ca37cc84426514b08923818813192c3cb84a8a16');

            // Verifică rolul client
            if (decoded.role !== 'client') {
                SecurityLogger.logRoleAccess(decoded.userId, decoded.role, req.path, false, req.ip);
                return res.status(403).json({
                    error: 'Acces interzis. Doar clienții pot accesa meniul de programări.',
                    redirectTo: decoded.role === 'admin' ? '/admin/cpanel' : '/login'
                });
            }

            // Log successful client access
            SecurityLogger.logRoleAccess(decoded.userId, 'client', req.path, true, req.ip);

            req.user = decoded;
            req.clientAccess = true;
            next();

        } catch (error) {
            return res.status(401).json({
                error: 'Token invalid sau expirat.'
            });
        }
    }

    /**
     * Verifică dacă user poate accesa propriile date sau este admin
     * Implementează protecție IDOR (Insecure Direct Object References)
     * @param {Object} req - Express request object
     * @param {Object} res - Express response object
     * @param {Function} next - Express next function
     */
    static requireOwnershipOrAdmin(req, res, next) {
        try {
            const authHeader = req.headers.authorization;

            if (!authHeader || !authHeader.startsWith('Bearer ')) {
                return res.status(401).json({
                    error: 'Autentificare necesară.'
                });
            }

            const token = authHeader.split(' ')[1];
            const decoded = jwt.verify(token, process.env.JWT_SECRET || 'ca37cc84426514b08923818813192c3cb84a8a16');

            const requestedUserId = req.params.userId || req.body.userId || req.query.userId;

            // Admin poate accesa orice
            if (decoded.role === 'admin') {
                req.user = decoded;
                req.isOwnerOrAdmin = true;
                return next();
            }

            // Client poate accesa doar propriile date
            if (decoded.role === 'client' && decoded.userId === requestedUserId) {
                req.user = decoded;
                req.isOwnerOrAdmin = true;
                return next();
            }

            // Logează tentativa de acces neautorizat
            SecurityLogger.logSuspiciousActivity(decoded.userId, 'UNAUTHORIZED_DATA_ACCESS', {
                requestedUserId,
                userRole: decoded.role,
                path: req.path,
                ip: req.ip
            });

            return res.status(403).json({
                error: 'Nu poți accesa datele altui utilizator. Acces interzis.'
            });

        } catch (error) {
            return res.status(401).json({
                error: 'Token invalid sau expirat.'
            });
        }
    }

    /**
     * Implementează protecția împotriva brute force attacks
     * @param {string} email - Email utilizator
     * @param {string} ip - IP address
     * @returns {Object} - Status lockout
     */
    checkBruteForceProtection(email, ip) {
        const key = "" + (email) + "_" + (ip) + "";
        const now = Date.now();

        if (!this.failedAttempts.has(key)) {
            this.failedAttempts.set(key, {
                count: 0,
                lastAttempt: now,
                lockoutUntil: 0
            });
        }

        const attempts = this.failedAttempts.get(key);

        // Verifică dacă încă este în lockout
        if (attempts.lockoutUntil > now) {
            const remainingTime = Math.ceil((attempts.lockoutUntil - now) / 1000);
            return {
                blocked: true,
                remainingTime,
                message: "Cont temporar blocat din motive de securitate. Încearcă din nou în " + (remainingTime) + " secunde."
            };
        }

        return { blocked: false };
    }

    /**
     * Înregistrează o încercare de autentificare eșuată
     * @param {string} email - Email utilizator
     * @param {string} ip - IP address
     */
    recordFailedAttempt(email, ip) {
        const key = "" + (email) + "_" + (ip) + "";
        const now = Date.now();

        if (!this.failedAttempts.has(key)) {
            this.failedAttempts.set(key, {
                count: 1,
                lastAttempt: now,
                lockoutUntil: 0
            });
            return;
        }

        const attempts = this.failedAttempts.get(key);
        attempts.count += 1;
        attempts.lastAttempt = now;

        // Calculează timpul de lockout cu exponential backoff
        if (attempts.count >= this.MAX_FAILED_ATTEMPTS) {
            const lockoutTime = Math.min(
                this.LOCKOUT_BASE_TIME * Math.pow(2, attempts.count - this.MAX_FAILED_ATTEMPTS),
                this.LOCKOUT_MAX_TIME
            );

            attempts.lockoutUntil = now + lockoutTime;

            SecurityLogger.logSuspiciousActivity(email, 'BRUTE_FORCE_DETECTED', {
                attempts: attempts.count,
                ip,
                lockoutTime: lockoutTime / 1000
            });
        }

        this.failedAttempts.set(key, attempts);
    }

    /**
     * Resetează încercările eșuate pentru un utilizator
     * @param {string} email - Email utilizator  
     * @param {string} ip - IP address
     */
    resetFailedAttempts(email, ip) {
        const key = "" + (email) + "_" + (ip) + "";
        this.failedAttempts.delete(key);
    }

    /**
     * Middleware pentru validarea input-urilor împotriva injection attacks
     * @param {Object} req - Express request object
     * @param {Object} res - Express response object
     * @param {Function} next - Express next function
     */
    static validateInput(req, res, next) {
        const suspiciousPatterns = [
            /(\<|%3C)script(\>|%3E)/gi, // XSS
            /union\s+select/gi, // SQL Injection
            /drop\s+table/gi, // SQL Injection
            /\.\.\/|\.\.%2F/gi, // Path Traversal
            /\$\{.*\}/gi, // Template Injection
            /javascript:/gi, // JavaScript protocol
            /<iframe/gi, // Iframe injection
            /on\w+\s*=/gi // Event handler injection
        ];

        const checkValue = function (value, path = '') {
            if (typeof value === 'string') {
                for (const pattern of suspiciousPatterns) {
                    if (pattern.test(value)) {
                        SecurityLogger.logSuspiciousActivity(
                            req.user?.userId || 'unknown',
                            'INJECTION_ATTEMPT',
                            {
                                pattern: pattern.toString(),
                                value: value.substring(0, 100), // Limitează lungimea log-ului
                                path,
                                ip: req.ip
                            }
                        );

                        return res.status(400).json({
                            error: 'Input invalid detectat. Te rugăm să verifici datele introduse.'
                        });
                    }
                }
            } else if (typeof value === 'object' && value !== null) {
                for (const [key, val] of Object.entries(value)) {
                    const result = checkValue(val, "" + (path) + "." + (key) + "");
                    if (result) return result;
                }
            }
        };

        // Verifică body, query și params
        checkValue(req.body, 'body');
        checkValue(req.query, 'query');
        checkValue(req.params, 'params');

        next();
    }

    /**
     * Middleware general pentru autentificare (orice rol)
     * @param {Object} req - Express request object
     * @param {Object} res - Express response object
     * @param {Function} next - Express next function
     */
    static requireAuth(req, res, next) {
        try {
            // Mai întâi încearcă Authorization header (JWT)
            const authHeader = req.headers.authorization;

            if (authHeader && authHeader.startsWith('Bearer ')) {
                const token = authHeader.split(' ')[1];

                if (!token) {
                    return res.status(401).json({
                        success: false,
                        error: 'Format token invalid.'
                    });
                }

                const decoded = jwt.verify(token, process.env.JWT_SECRET || 'ca37cc84426514b08923818813192c3cb84a8a16');

                // Verifică dacă token-ul nu a expirat
                if (decoded.exp && decoded.exp < Date.now() / 1000) {
                    return res.status(401).json({
                        success: false,
                        error: 'Token-ul a expirat. Te rugăm să te autentifici din nou.'
                    });
                }

                SecurityLogger.logRoleAccess(decoded.id || decoded.userId, decoded.role, req.path, true, req.ip);

                req.user = {
                    id: decoded.id || decoded.userId,
                    userId: decoded.id || decoded.userId, // pentru compatibilitate
                    email: decoded.email,
                    role: decoded.role,
                    firstName: decoded.firstName,
                    lastName: decoded.lastName
                };

                return next();
            }

            // Dacă nu există Authorization header, încearcă cookie-ul auth_session
            const sessionId = req.cookies.auth_session;

            if (!sessionId) {
                return res.status(401).json({
                    success: false,
                    error: 'Token de autentificare lipsa. Te rugăm să te autentifici.'
                });
            }

            // Pentru simplitate, setăm req.user cu ID-ul din cookie
            // În producție ar trebui să verificăm sesiunea în baza de date
            req.user = {
                id: sessionId,
                userId: sessionId,
                email: 'unknown', // Nu avem email în cookie
                role: 'client', // Presupunem client
                firstName: 'Unknown',
                lastName: 'User'
            };

            next();

        } catch (error) {
            console.error('Eroare la verificarea autentificării:', error.message);

            if (error.name === 'JsonWebTokenError') {
                return res.status(401).json({
                    success: false,
                    error: 'Token invalid.'
                });
            } else if (error.name === 'TokenExpiredError') {
                return res.status(401).json({
                    success: false,
                    error: 'Token-ul a expirat. Te rugăm să te autentifici din nou.'
                });
            }

            return res.status(401).json({
                success: false,
                error: 'Eroare la autentificare.'
            });
        }
    }

    /**
     * Middleware pentru verificarea proprietății (user poate accesa doar propriile resurse)
     * @param {Object} req - Express request object
     * @param {Object} res - Express response object
     * @param {Function} next - Express next function
     */
    static requireOwnership(req, res, next) {
        try {
            const authHeader = req.headers.authorization;

            if (!authHeader || !authHeader.startsWith('Bearer ')) {
                return res.status(401).json({
                    success: false,
                    error: 'Autentificare necesară.'
                });
            }

            const token = authHeader.split(' ')[1];
            const decoded = jwt.verify(token, process.env.JWT_SECRET || 'ca37cc84426514b08923818813192c3cb84a8a16');

            const requestedUserId = req.params.userId || req.params.id;

            // Admin poate accesa orice
            if (decoded.role === 'admin') {
                req.user = {
                    id: decoded.id || decoded.userId,
                    userId: decoded.id || decoded.userId,
                    email: decoded.email,
                    role: decoded.role,
                    firstName: decoded.firstName,
                    lastName: decoded.lastName
                };
                return next();
            }

            // User poate accesa doar propriile resurse
            const userId = decoded.id || decoded.userId;
            if (requestedUserId && requestedUserId !== userId.toString()) {
                SecurityLogger.logSuspiciousActivity(userId, 'UNAUTHORIZED_RESOURCE_ACCESS', {
                    requestedResource: requestedUserId,
                    userRole: decoded.role,
                    endpoint: req.path
                });

                return res.status(403).json({
                    success: false,
                    error: 'Nu poți accesa resursa altui utilizator.'
                });
            }

            req.user = {
                id: userId,
                userId: userId,
                email: decoded.email,
                role: decoded.role,
                firstName: decoded.firstName,
                lastName: decoded.lastName
            };

            next();

        } catch (error) {
            console.error('Eroare la verificarea proprietății:', error.message);
            return res.status(401).json({
                success: false,
                error: 'Token invalid sau expirat.'
            });
        }
    }
}

/**
 * Security Logger pentru monitorizarea activităților suspecte
 */
class SecurityLogger {
    static logAuthAttempt(email, success, ip, userAgent) {
        const logEntry = {
            timestamp: new Date().toISOString(),
            type: 'AUTH_ATTEMPT',
            email,
            success,
            ip,
            userAgent,
            risk_level: success ? 'LOW' : 'MEDIUM'
        };

        console.log('SECURITY_LOG:', JSON.stringify(logEntry));

        try {
            if (!fs.existsSync('./logs')) {
                fs.mkdirSync('./logs', { recursive: true });
            }
            fs.appendFileSync('./logs/security.log', JSON.stringify(logEntry) + '\n');
        } catch (error) {
            console.error('Eroare la scrierea log-ului de securitate:', error);
        }
    }

    static logRoleAccess(userId, role, endpoint, success, ip) {
        const logEntry = {
            timestamp: new Date().toISOString(),
            type: 'ROLE_ACCESS',
            userId,
            role,
            endpoint,
            success,
            ip,
            risk_level: success ? 'LOW' : (role !== 'admin' ? 'HIGH' : 'MEDIUM')
        };

        console.log('SECURITY_LOG:', JSON.stringify(logEntry));

        try {
            if (!fs.existsSync('./logs')) {
                fs.mkdirSync('./logs', { recursive: true });
            }
            fs.appendFileSync('./logs/security.log', JSON.stringify(logEntry) + '\n');
        } catch (error) {
            console.error('Eroare la scrierea log-ului de securitate:', error);
        }
    }

    static logSuspiciousActivity(userId, activity, details) {
        const logEntry = {
            timestamp: new Date().toISOString(),
            type: 'SUSPICIOUS_ACTIVITY',
            userId,
            activity,
            details,
            risk_level: 'HIGH'
        };

        console.log('SECURITY_ALERT:', JSON.stringify(logEntry));

        try {
            if (!fs.existsSync('./logs')) {
                fs.mkdirSync('./logs', { recursive: true });
            }
            fs.appendFileSync('./logs/security.log', JSON.stringify(logEntry) + '\n');
        } catch (error) {
            console.error('Eroare la scrierea log-ului de securitate:', error);
        }

        // În producție, aici ar putea trimite alertă către admin
        if (process.env.NODE_ENV === 'production') {
            // TODO: Implementează alertele către admin (email/SMS)
            console.error('HIGH RISK SECURITY EVENT:', logEntry);
        }
    }
}

// Singleton instance pentru brute force protection
const authMiddleware = new AuthMiddleware();

module.exports = {
    AuthMiddleware,
    SecurityLogger,
    requireAdmin: AuthMiddleware.requireAdmin,
    requireClient: AuthMiddleware.requireClient,
    requireAuth: AuthMiddleware.requireAuth,
    requireOwnership: AuthMiddleware.requireOwnership,
    requireOwnershipOrAdmin: AuthMiddleware.requireOwnershipOrAdmin,
    validateInput: AuthMiddleware.validateInput,
    checkBruteForce: function (email, ip) { return authMiddleware.checkBruteForceProtection(email, ip); },
    recordFailedAttempt: function (email, ip) { return authMiddleware.recordFailedAttempt(email, ip); },
    resetFailedAttempts: function (email, ip) { return authMiddleware.resetFailedAttempts(email, ip); }};

var ENIP = require.ENIP;
var CIP = require.CIP;("../enip");
const dateFormat = require("dateformat");
const TagGroup = require("../tag-group");
var delay = require.delay;
var promiseTimeout = require.promiseTimeout;("../utilities");
const Queue = require("task-easy");

const compare = function (obj1, obj2) {
    if (obj1.priority > obj2.priority) return true;
    else if (obj1.priority < obj2.priority) return false;
    else return obj1.timestamp.getTime() < obj2.timestamp.getTime();
};

class Controller extends ENIP {
    constructor({ queue_max_size } = {}) {
        super();

        this.state = {
            ...this.state,
            controller: {
                name: null,
                serial_number: null,
                slot: null,
                time: null,
                path: null,
                version: null,
                status: null,
                faulted: false,
                minorRecoverableFault: false,
                minorUnrecoverableFault: false,
                majorRecoverableFault: false,
                majorUnrecoverableFault: false,
                io_faulted: false
            },
            subs: new TagGroup(compare),
            scanning: false,
            scan_rate: 200 //ms
        };

        this.workers = {
            read: new Queue(compare, queue_max_size),
            write: new Queue(compare, queue_max_size),
            group: new Queue(compare, queue_max_size)
        };
    }

    // region Property Definitions
    /**
     * Returns the Scan Rate of Subscription Tags
     *
     * @memberof Controller
     * @returns {number} ms
     */
    get scan_rate() {
        return this.state.scan_rate;
    }

    /**
     * Sets the Subsciption Group Scan Rate
     *
     * @memberof Controller
     */
    set scan_rate(rate) {
        if (typeof rate !== "number") throw new Error("scan_rate must be of Type <number>");
        this.state.scan_rate = Math.trunc(rate);
    }

    /**
     * Get the status of Scan Group
     *
     * @readonly
     * @memberof Controller
     */
    get scanning() {
        return this.state.scanning;
    }

    /**
     * Gets the Controller Properties Object
     *
     * @readonly
     * @memberof Controller
     * @returns {object}
     */
    get properties() {
        return this.state.controller;
    }

    /**
     * Fetches the last timestamp retrieved from the controller
     * in human readable form
     *
     * @readonly
     * @memberof Controller
     */
    get time() {
        return dateFormat(this.state.controller.time, "mmmm dd, yyyy - hh:MM:ss TT");
    }
    // endregion

    // region Public Method Definitions
    /**
     * Initializes Session with Desired IP Address
     * and Returns a Promise with the Established Session ID
     *
     * @override
     * @param {string} IP_ADDR - IPv4 Address (can also accept a FQDN, provided port forwarding is configured correctly.)
     * @param {number} SLOT - Controller Slot Number (0 if CompactLogix)
     * @returns {Promise}
     * @memberof ENIP
     */
    async connect(IP_ADDR, SLOT = 0) {
        var PORT = CIP.EPATH.segments.PORT;
        const BACKPLANE = 1;

        this.state.controller.slot = SLOT;
        this.state.controller.path = PORT.build(BACKPLANE, SLOT);

        const sessid = await super.connect(IP_ADDR);

        if (!sessid) throw new Error("Failed to Register Session with Controller");

        this._initializeControllerEventHandlers();

        // Fetch Controller Properties and Wall Clock
        await this.readControllerProps();
    }

    /**
     * Writes Ethernet/IP Data to Socket as an Unconnected Message
     * or a Transport Class 1 Datagram
     *
     * NOTE: Cant Override Socket Write due to net.Socket.write
     *        implementation. =[. Thus, I am spinning up a new Method to
     *        handle it. Dont Use Enip.write, use this function instead.
     *
     * @override
     * @param {buffer} data - Message Router Packet Buffer
     * @param {boolean} [connected=false]
     * @param {number} [timeout=10] - Timeoue (sec)
     * @param {function} [cb=null] - Callback to be Passed to Parent.Write()
     * @memberof ENIP
     */
    write_cip(data, connected = false, timeout = 10, cb = null) {
        var UnconnectedSend = CIP.UnconnectedSend;

        const msg = UnconnectedSend.build(data, this.state.controller.path);

        //TODO: Implement Connected Version
        super.write_cip(msg, connected, timeout, cb);
    }

    /**
     * Reads Controller Identity Object
     *
     * @memberof Controller
     * @returns {Promise}
     */
    async readControllerProps() {
        var GET_ATTRIBUTE_ALL = CIP.MessageRouter.services.GET_ATTRIBUTE_ALL;
        var LOGICAL = CIP.EPATH.segments.LOGICAL;

        // Build Identity Object Logical Path Buffer
        const identityPath = Buffer.concat([
            LOGICAL.build(LOGICAL.types.ClassID, 0x01), // Identity Object (0x01)
            LOGICAL.build(LOGICAL.types.InstanceID, 0x01) // Instance ID (0x01)
        ]);

        // Message Router to Embed in UCMM
        const MR = CIP.MessageRouter.build(GET_ATTRIBUTE_ALL, identityPath, []);

        this.write_cip(MR);

        const readPropsErr = new Error("TIMEOUT occurred while reading Controller Props.");

        // Wait for Response
        const data = await promiseTimeout(
            new Promise(function (resolve, reject) {
                this.on("Get Attribute All", (err, data) => {
                    if (err) reject(err);
                    resolve(data);
                });
            }),
            10000,
            readPropsErr
        );

        this.removeAllListeners("Get Attribute All");

        // Parse Returned Buffer
        this.state.controller.serial_number = data.readUInt32LE(10);

        const nameBuf = Buffer.alloc(data.length - 15);
        data.copy(nameBuf, 0, 15);

        this.state.controller.name = nameBuf.toString("utf8");

        const major = data.readUInt8(6);
        const minor = data.readUInt8(7);
        this.state.controller.version = "" + (major) + "." + (minor) + "";

        let status = data.readUInt16LE(8);
        this.state.controller.status = status;

        status &= 0x0ff0;
        this.state.controller.faulted = (status & 0x0f00) === 0 ? false : true;
        this.state.controller.minorRecoverableFault = (status & 0x0100) === 0 ? false : true;
        this.state.controller.minorUnrecoverableFault = (status & 0x0200) === 0 ? false : true;
        this.state.controller.majorRecoverableFault = (status & 0x0400) === 0 ? false : true;
        this.state.controller.majorUnrecoverableFault = (status & 0x0800) === 0 ? false : true;

        status &= 0x0f00;
        this.state.controller.io_faulted = status >> 4 === 2 ? true : false;
        this.state.controller.faulted = status >> 4 === 2 ? true : this.state.controller.faulted;
    }

    /**
     * Reads the Controller Wall Clock Object
     *
     * @memberof Controller
     * @returns {Promise}
     */
    async readWallClock() {
        if (this.state.controller.name.search("L8") === -1)
            throw new Error("WallClock Utilities are not supported by this controller type");

        var GET_ATTRIBUTE_SINGLE = CIP.MessageRouter.services.GET_ATTRIBUTE_SINGLE;
        var LOGICAL = CIP.EPATH.segments.LOGICAL;

        // Build Identity Object Logical Path Buffer
        const identityPath = Buffer.concat([
            LOGICAL.build(LOGICAL.types.ClassID, 0x8b), // WallClock Object (0x8B)
            LOGICAL.build(LOGICAL.types.InstanceID, 0x01), // Instance ID (0x01)
            LOGICAL.build(LOGICAL.types.AttributeID, 0x05) // Local Time Attribute ID
        ]);

        // Message Router to Embed in UCMM
        const MR = CIP.MessageRouter.build(GET_ATTRIBUTE_SINGLE, identityPath, []);

        this.write_cip(MR);

        const readPropsErr = new Error("TIMEOUT occurred while reading Controller Clock.");

        // Wait for Response
        const data = await promiseTimeout(
            new Promise(function (resolve, reject) {
                this.on("Get Attribute Single", (err, data) => {
                    if (err) reject(err);
                    resolve(data);
                });
            }),
            10000,
            readPropsErr
        );

        this.removeAllListeners("Get Attribute Single");

        // Parse Returned Buffer
        let wallClockArray = [];
        for (let i = 0; i < 7; i++) {
            wallClockArray.push(data.readUInt32LE(i * 4));
        }

        // Massage Data to JS Date Friendly Format
        wallClockArray[6] = Math.trunc(wallClockArray[6] / 1000); // convert to ms from us
        wallClockArray[1] -= 1; // month is 0-based

        const date = new Date(...wallClockArray);
        this.state.controller.time = date;
    }

    /**
     * Write to PLC Wall Clock
     *
     * @param {Date} [date=new Date()]
     * @memberof Controller
     * @returns {Promise}
     */
    async writeWallClock(date = new Date()) {
        if (this.state.controller.name.search("L8") === -1)
            throw new Error("WallClock Utilities are not supported by this controller type");

        var SET_ATTRIBUTE_SINGLE = CIP.MessageRouter.services.SET_ATTRIBUTE_SINGLE;
        var LOGICAL = CIP.EPATH.segments.LOGICAL;
        const arr = [];

        arr.push(date.getFullYear());
        arr.push(date.getMonth() + 1);
        arr.push(date.getDate());
        arr.push(date.getHours());
        arr.push(date.getMinutes());
        arr.push(date.getSeconds());
        arr.push(date.getMilliseconds() * 1000);

        let buf = Buffer.alloc(28);
        for (let i = 0; i < 7; i++) {
            buf.writeUInt32LE(arr[i], 4 * i);
        }

        // Build Identity Object Logical Path Buffer
        const identityPath = Buffer.concat([
            LOGICAL.build(LOGICAL.types.ClassID, 0x8b), // WallClock Object (0x8B)
            LOGICAL.build(LOGICAL.types.InstanceID, 0x01), // Instance ID (0x01)
            LOGICAL.build(LOGICAL.types.AttributeID, 0x05) // Local Time Attribute ID
        ]);

        // Message Router to Embed in UCMM
        const MR = CIP.MessageRouter.build(SET_ATTRIBUTE_SINGLE, identityPath, buf);

        this.write_cip(MR);

        const writeClockErr = new Error("TIMEOUT occurred while writing Controller Clock.");

        // Wait for Response
        await promiseTimeout(
            new Promise(function (resolve, reject) {
                this.on("Set Attribute Single", (err, data) => {
                    if (err) reject(err);
                    resolve(data);
                });
            }),
            10000,
            writeClockErr
        );

        this.removeAllListeners("Set Attribute Single");

        this.state.controller.time = date;
    }

    /**
     * Reads Value of Tag and Type from Controller
     *
     * @param {Tag} tag - Tag Object to Write
     * @param {number} [size=null]
     * @returns {Promise}
     * @memberof Controller
     */
    readTag(tag, size = null) {
        return this.workers.read.schedule(this._readTag.bind(this), [tag, size], {
            priority: 1,
            timestamp: new Date()
        });
    }

    /**
     * Writes value to Tag
     *
     * @param {Tag} tag - Tag Object to Write
     * @param {number|boolean|object|string} [value=null] - If Omitted, Tag.value will be used
     * @param {number} [size=0x01]
     * @returns {Promise}
     * @memberof Controller
     */
    writeTag(tag, value = null, size = 0x01) {
        return this.workers.write.schedule(this._writeTag.bind(this), [tag, value, size], {
            priority: 1,
            timestamp: new Date()
        });
    }

    /**
     * Reads All Tags in the Passed Tag Group
     *
     * @param {TagGroup} group
     * @returns {Promise}
     * @memberof Controller
     */
    readTagGroup(group) {
        return this.workers.group.schedule(this._readTagGroup.bind(this), [group], {
            priority: 1,
            timestamp: new Date()
        });
    }

    /**
     * Writes to Tag Group Tags
     *
     * @param {TAgGroup} group
     * @returns {Promise}
     * @memberof Controller
     */
    writeTagGroup(group) {
        return this.workers.group.schedule(this._writeTagGroup.bind(this), [group], {
            priority: 1,
            timestamp: new Date()
        });
    }

    /**
     * Adds Tag to Subscription Group
     *
     * @param {Tagany} tag
     * @memberof Controller
     */
    subscribe(tag) {
        this.state.subs.add(tag);
    }

    /**
     * Begin Scanning Subscription Group
     *
     * @memberof Controller
     */
    async scan() {
        this.state.scanning = true;

        while (this.state.scanning) {
            await this.workers.group
                .schedule(this._readTagGroup.bind(this), [this.state.subs], {
                    priority: 10,
                    timestamp: new Date()
                })
                .catch(function e {
                    if (e.message) {
                        throw new Error("<SCAN_GROUP>\n " + (e.message) + "");
                    } else {
                        throw e;
                    }
                });

            await this.workers.group
                .schedule(this._writeTagGroup.bind(this), [this.state.subs], {
                    priority: 10,
                    timestamp: new Date()
                })
                .catch(function e {
                    if (e.message) {
                        throw new Error("<SCAN_GROUP>\n " + (e.message) + "");
                    } else {
                        throw e;
                    }
                });

            await delay(this.state.scan_rate);
        }
    }

    /**
     * Pauses Scanning of Subscription Group
     *
     * @memberof Controller
     */
    pauseScan() {
        this.state.scanning = false;
    }

    /**
     * Iterates of each tag in Subscription Group
     *
     * @param {function} callback
     * @memberof Controller
     */
    forEach(callback) {
        this.state.subs.forEach(callback);
    }
    // endregion

    // region Private Methods
    /**
     * Initialized Controller Specific Event Handlers
     *
     * @memberof Controller
     */
    _initializeControllerEventHandlers() {
        this.on("SendRRData Received", this._handleSendRRDataReceived);
    }

    /**
     * Reads Value of Tag and Type from Controller
     *
     * @param {Tag} tag - Tag Object to Write
     * @param {number} [size=null]
     * @returns {Promise}
     * @memberof Controller
     */
    async _readTag(tag, size = null) {
        const MR = tag.generateReadMessageRequest(size);

        this.write_cip(MR);

        const readTagErr = new Error("TIMEOUT occurred while writing Reading Tag: " + (tag.name) + ".");

        // Wait for Response
        const data = await promiseTimeout(
            new Promise(function (resolve, reject) {
                this.on("Read Tag", (err, data) => {
                    if (err) reject(err);
                    resolve(data);
                });
            }),
            10000,
            readTagErr
        );

        this.removeAllListeners("Read Tag");

        tag.parseReadMessageResponse(data);
    }

    /**
     * Writes value to Tag
     *
     * @param {Tag} tag - Tag Object to Write
     * @param {number|boolean|object|string} [value=null] - If Omitted, Tag.value will be used
     * @param {number} [size=0x01]
     * @returns {Promise}
     * @memberof Controller
     */
    async _writeTag(tag, value = null, size = 0x01) {
        const MR = tag.generateWriteMessageRequest(value, size);

        this.write_cip(MR);

        const writeTagErr = new Error("TIMEOUT occurred while writing Writing Tag: " + (tag.name) + ".");

        // Wait for Response
        await promiseTimeout(
            new Promise(function (resolve, reject) {

                // Full Tag Writing
                this.on("Write Tag", (err, data) => {
                    if (err) reject(err);

                    tag.unstageWriteRequest();
                    resolve(data);
                });

                // Masked Bit Writing
                this.on("Read Modify Write Tag", (err, data) => {
                    if (err) reject(err);

                    tag.unstageWriteRequest();
                    resolve(data);
                });
            }),
            10000,
            writeTagErr
        );

        this.removeAllListeners("Write Tag");
        this.removeAllListeners("Read Modify Write Tag");
    }

    /**
     * Reads All Tags in the Passed Tag Group
     *
     * @param {TagGroup} group
     * @returns {Promise}
     * @memberof Controller
     */
    async _readTagGroup(group) {
        const messages = group.generateReadMessageRequests();

        const readTagGroupErr = new Error("TIMEOUT occurred while writing Reading Tag Group.");

        // Send Each Multi Service Message
        for (let msg of messages) {
            this.write_cip(msg.data);

            // Wait for Controller to Respond
            const data = await promiseTimeout(
                new Promise(function (resolve, reject) {
                    this.on("Multiple Service Packet", (err, data) => {
                        if (err) reject(err);

                        resolve(data);
                    });
                }),
                10000,
                readTagGroupErr
            );

            this.removeAllListeners("Multiple Service Packet");

            // Parse Messages
            group.parseReadMessageResponses(data, msg.tag_ids);
        }
    }

    /**
     * Writes to Tag Group Tags
     *
     * @param {TagGroup} group
     * @returns {Promise}
     * @memberof Controller
     */
    async _writeTagGroup(group) {
        const messages = group.generateWriteMessageRequests();

        const writeTagGroupErr = new Error("TIMEOUT occurred while writing Writing Tag Group.");

        // Send Each Multi Service Message
        for (let msg of messages) {
            this.write_cip(msg.data);

            // Wait for Controller to Respond
            const data = await promiseTimeout(
                new Promise(function (resolve, reject) {
                    this.on("Multiple Service Packet", (err, data) => {
                        if (err) reject(err);

                        resolve(data);
                    });
                }),
                10000,
                writeTagGroupErr
            );

            this.removeAllListeners("Multiple Service Packet");

            group.parseWriteMessageRequests(data, msg.tag_ids);
        }
    }
    // endregion

    // region Event Handlers
    /**
     * @typedef EncapsulationData
     * @type {Object}
     * @property {number} commandCode - Ecapsulation Command Code
     * @property {string} command - Encapsulation Command String Interpretation
     * @property {number} length - Length of Encapsulated Data
     * @property {number} session - Session ID
     * @property {number} statusCode - Status Code
     * @property {string} status - Status Code String Interpretation
     * @property {number} options - Options (Typically 0x00)
     * @property {Buffer} data - Encapsulated Data Buffer
     */
    /*****************************************************************/

    /**
     * @typedef MessageRouter
     * @type {Object}
     * @property {number} service - Reply Service Code
     * @property {number} generalStatusCode - General Status Code (Vol 1 - Appendix B)
     * @property {number} extendedStatusLength - Length of Extended Status (In 16-bit Words)
     * @property {Array} extendedStatus - Extended Status
     * @property {Buffer} data - Status Code
     */
    /*****************************************************************/

    /**
     * Handles SendRRData Event Emmitted by Parent and Routes
     * incoming Message
     *
     * @param {Array} srrd - Array of Common Packet Formatted Objects
     * @memberof Controller
     */
    _handleSendRRDataReceived(srrd) {
        var service = CIP.MessageRouter.parse.service;
var generalStatusCode = CIP.MessageRouter.parse.generalStatusCode;
var extendedStatus = CIP.MessageRouter.parse.extendedStatus;
var data = CIP.MessageRouter.parse.data;(
            srrd[1].data
        );

        var GET_ATTRIBUTE_SINGLE = CIP.MessageRouter.services.GET_ATTRIBUTE_SINGLE;
var GET_ATTRIBUTE_ALL = CIP.MessageRouter.services.GET_ATTRIBUTE_ALL;
var SET_ATTRIBUTE_SINGLE = CIP.MessageRouter.services.SET_ATTRIBUTE_SINGLE;
var READ_TAG = CIP.MessageRouter.services.READ_TAG;
var READ_TAG_FRAGMENTED = CIP.MessageRouter.services.READ_TAG_FRAGMENTED;
var WRITE_TAG = CIP.MessageRouter.services.WRITE_TAG;
var WRITE_TAG_FRAGMENTED = CIP.MessageRouter.services.WRITE_TAG_FRAGMENTED;
var READ_MODIFY_WRITE_TAG = CIP.MessageRouter.services.READ_MODIFY_WRITE_TAG;
var MULTIPLE_SERVICE_PACKET = CIP.MessageRouter.services.MULTIPLE_SERVICE_PACKET;

        let error = generalStatusCode !== 0 ? { generalStatusCode, extendedStatus } : null;

        // Route Incoming Message Responses
        /* eslint-disable indent */
        switch (service - 0x80) {
            case GET_ATTRIBUTE_SINGLE:
                this.emit("Get Attribute Single", error, data);
                break;
            case GET_ATTRIBUTE_ALL:
                this.emit("Get Attribute All", error, data);
                break;
            case SET_ATTRIBUTE_SINGLE:
                this.emit("Set Attribute Single", error, data);
                break;
            case READ_TAG:
                this.emit("Read Tag", error, data);
                break;
            case READ_TAG_FRAGMENTED:
                this.emit("Read Tag Fragmented", error, data);
                break;
            case WRITE_TAG:
                this.emit("Write Tag", error, data);
                break;
            case WRITE_TAG_FRAGMENTED:
                this.emit("Write Tag Fragmented", error, data);
                break;            
            case READ_MODIFY_WRITE_TAG:
                this.emit("Read Modify Write Tag", error, data);
                break;
            case MULTIPLE_SERVICE_PACKET: {
                // If service errored then propogate error
                if (error) {
                    this.emit("Multiple Service Packet", error, data);
                    break;
                }

                // Get Number of Services to be Enclosed
                let services = data.readUInt16LE(0);
                let offsets = [];
                let responses = [];

                // Build Array of Buffer Offsets
                for (let i = 0; i < services; i++) {
                    offsets.push(data.readUInt16LE(i * 2 + 2));
                }

                // Gather Messages within Buffer
                for (let i = 0; i < offsets.length - 1; i++) {
                    const length = offsets[i + 1] - offsets[i];

                    let buf = Buffer.alloc(length);
                    data.copy(buf, 0, offsets[i], offsets[i + 1]);

                    // Parse Message Data
                    const msgData = CIP.MessageRouter.parse(buf);

                    if (msgData.generalStatusCode !== 0) {
                        error = {
                            generalStatusCode: msgData.generalStatusCode,
                            extendedStatus: msgData.extendedStatus
                        };
                    }

                    responses.push(msgData);
                }

                // Handle Final Message
                const length = data.length - offsets[offsets.length - 1];

                let buf = Buffer.alloc(length);
                data.copy(buf, 0, offsets[offsets.length - 1]);

                const msgData = CIP.MessageRouter.parse(buf);

                if (msgData.generalStatusCode !== 0) {
                    error = {
                        generalStatusCode: msgData.generalStatusCode,
                        extendedStatus: msgData.extendedStatus
                    };
                }

                responses.push(msgData);

                this.emit("Multiple Service Packet", error, responses);
                break;
            }
            default:
                this.emit("Unknown Reply", { generalStatusCode: 0x99, extendedStatus: [] }, data);
                break;
        }
        /* eslint-enable indent */
    }

    // _handleSendUnitDataReceived(data) {
    //     // TODO: Implement when ready for Connected Messaging
    // }

    // _handleSessionRegistrationFailed(error) {
    //     // TODO: Implement Handler if Necessary
    // }
    // endregion
}

module.exports = Controller;

