/**
 * Time MVC Module
 * 
 * This module handles time-related functionality including:
 * - Multiple timezone display
 * - DST information
 * - Week number calculation
 * - Timezone selection
 * 
 * Parts of this code were developed with assistance from GitHub Copilot.
 * See ATTRIBUTION.md for details about AI contributions.
 */
var calendarDate = new Date();

var formatNumber = function (n) {
  if (n < 10) {
      return "0" + n;
  }
  return "" + n;
}

var getUtcDaytime = function (date) {    
  var y = date.getUTCFullYear();
  var M = formatNumber(date.getUTCMonth() + 1);
  var D = formatNumber(date.getUTCDate());
  var h = formatNumber(date.getUTCHours());
  var m = formatNumber(date.getUTCMinutes());
  var s = formatNumber(date.getUTCSeconds());
  return y + "-" + M + "-" + D + " " + h + ":" + m + ":" + s + " (UTC)";
}

var getGmtDaytime = function (date) {    
  var offset = date.getTimezoneOffset();
  var gmtDate = new Date(date.getTime() + offset * 60 * 1000);
  var y = gmtDate.getFullYear();
  var M = formatNumber(gmtDate.getMonth() + 1);
  var D = formatNumber(gmtDate.getDate());
  var h = formatNumber(gmtDate.getHours());
  var m = formatNumber(gmtDate.getMinutes());
  var s = formatNumber(gmtDate.getSeconds());
  return y + "-" + M + "-" + D + " " + h + ":" + m + ":" + s + " (GMT)";
}

var getWeekNumber = function (date) {
  var d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  var dayNum = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
  var yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
}

var getOrganizedTimezones = function () {
  var zones = Intl.supportedValuesOf('timeZone');
  var organized = {};

  zones.forEach(tz => {
      var [continent, ...parts] = tz.split('/');
      if (!organized[continent]) {
          organized[continent] = [];
      }
      organized[continent].push({
          id: tz,
          name: parts.join('/').replace(/_/g, ' ')
      });
  });

  return organized;
};

var getDstInfo = function (date) {
    var jan = new Date(date.getFullYear(), 0, 1).getTimezoneOffset();
    var jul = new Date(date.getFullYear(), 6, 1).getTimezoneOffset();
    var stdTimezoneOffset = Math.max(jan, jul);
    var summerOffset = Math.min(jan, jul);

    var year = date.getFullYear();
    // Last Sunday in March at 02:00
    var summerDate = new Date(year, 2, 31 - new Date(year, 2, 31).getDay(), 2, 0, 0);
    // Last Sunday in October at 03:00
    var winterDate = new Date(year, 9, 31 - new Date(year, 9, 31).getDay(), 3, 0, 0);

    return {
        winter: "UTC" + (stdTimezoneOffset > 0 ? '-' : '+') + "" + (Math.abs(Math.floor(stdTimezoneOffset/60))) + ":" + (formatNumber(stdTimezoneOffset%60)) + "",
        summer: "UTC" + (summerOffset > 0 ? '-' : '+') + "" + (Math.abs(Math.floor(summerOffset/60))) + ":" + (formatNumber(summerOffset%60)) + "",
        current: date.getTimezoneOffset() < stdTimezoneOffset ? "Summer Time" : "Winter Time",
        summerStart: "" + (summerDate.toLocaleString('sv-SE', { 
            month: 'long', 
            day: 'numeric'
        })) + " kl. 02:00",
        winterStart: "" + (winterDate.toLocaleString('sv-SE', { 
            month: 'long', 
            day: 'numeric'
        })) + " kl. 03:00"
    };
}

var getSelectedTimeZoneTime = function (date, timezone) {
  var options = {
      timeZone: timezone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false
  };
  return date.toLocaleString('sv', options) + " (" + (timezone) + ")";
};

var getTimezoneSelectHtml = function (selectedTimezone) {
  var organized = getOrganizedTimezones();

  return Object.entries(organized)
      .map(([continent, zones]) => '
          <optgroup label="' + (continent.replace(/_/g, ' ')) + '">
              ' + (zones.map(zone => `
                  <option value="${zone.id}" 
                          ${zone.id === selectedTimezone ? 'selected' : ''}>
                      ${zone.name || zone.id}
                  </option>
              `).join('')) + "
          </optgroup>
      ").join('');
};

const getLocaleDaytime = (date) => {    
  const y = date.getFullYear();
  const M = formatNumber(date.getMonth() + 1);
  const D = formatNumber(date.getDate());
  const h = formatNumber(date.getHours());
  const m = formatNumber(date.getMinutes());
  const s = formatNumber(date.getSeconds());
  const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
  const epoch = Math.floor(date.getTime() / 1000);  // Convert to Unix epoch (seconds)
  const currentDate = {
      year: y,
      month: date.toLocaleString('en-US', { month: 'long' }),
      weekday: date.toLocaleString('en-US', { weekday: 'long' }),
      epoch: epoch,
      timezone: timezone
  };
  return {
      datetime: "" + (y) + "-" + (M) + "-" + (D) + " " + (h) + ":" + (m) + ":" + (s) + " (" + (timezone) + ")",
      current: currentDate
  };
}

const convertEpochToLocalTime = (epoch, timezone) => {
  const date = new Date(epoch * 1000); // Convert seconds to milliseconds
  const weekNumber = getWeekNumber(date);
  const options = {
      timeZone: timezone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
      weekday: 'long'
  };

  return {
      datetime: date.toLocaleString('sv', options) + " (" + (timezone) + ")",
      weekNumber: weekNumber,
      weekday: date.toLocaleString('en-US', { weekday: 'long', timeZone: timezone }),
      month: date.toLocaleString('en-US', { month: 'long', timeZone: timezone }),
      year: date.toLocaleString('en-US', { year: 'numeric', timeZone: timezone })
  };
};


